/* ==================================================================== */
/* Date & format helpers                                                 */
/* ==================================================================== */
const pad = (n) => String(n).padStart(2, "0");
const fmtDateUTC = (d) => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
const monthKey = (dateStr) => dateStr.slice(0, 7);

function getDailyTarget(targets, store, dateStr) {
  const mo = monthKey(dateStr);
  const rows = targets.filter((t) => (store === "ALL" || t.store === store) && (t.month === mo || t.month === "ALL"));
  if (rows.length === 0) return null;
  const monthlyTarget = rows.reduce((s, r) => s + r.target, 0);
  const [y, m] = dateStr.split("-").map(Number);
  const daysInMonth = new Date(Date.UTC(y, m, 0)).getUTCDate();
  return monthlyTarget / daysInMonth;
}

function shiftYearDate(dateStr, delta) {
  const [y, m, d] = dateStr.split("-").map(Number);
  return fmtDateUTC(new Date(Date.UTC(y + delta, m - 1, d)));
}
function shiftDaysDate(dateStr, delta) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + delta);
  return fmtDateUTC(dt);
}
function mondayOf(dateStr) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  const day = dt.getUTCDay();
  const diff = day === 0 ? -6 : 1 - day;
  dt.setUTCDate(dt.getUTCDate() + diff);
  return fmtDateUTC(dt);
}
function weekOptions(anchorDate, weeksBack = 11, weeksFwd = 1) {
  const startMonday = mondayOf(anchorDate);
  const out = [];
  for (let i = weeksFwd; i >= -weeksBack; i--) {
    const mon = shiftDaysDate(startMonday, i * 7);
    const sun = shiftDaysDate(mon, 6);
    out.push({ value: mon, label: `${mon} – ${sun}` });
  }
  return out;
}
function excelSerialToDate(serial) {
  const utcDays = Math.floor(serial - 25569);
  return new Date(utcDays * 86400 * 1000);
}
function findKey(row, candidates) {
  const keys = Object.keys(row);
  for (const c of candidates) {
    const hit = keys.find((k) => k.trim().toLowerCase() === c.toLowerCase());
    if (hit) return hit;
  }
  return null;
}
function normalizeDateValue(v) {
  if (v instanceof Date) return fmtDateUTC(v);
  if (typeof v === "number") return fmtDateUTC(excelSerialToDate(v));
  if (typeof v === "string") {
    const s = v.trim();
    const m1 = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
    if (m1) return `${m1[1]}-${pad(+m1[2])}-${pad(+m1[3])}`;
    const m2 = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    if (m2) return `${m2[3]}-${pad(+m2[1])}-${pad(+m2[2])}`;
    const parsed = new Date(s);
    if (!isNaN(parsed.getTime())) return fmtDateUTC(parsed);
  }
  return null;
}
function dateRangeArray(from, to) {
  const out = [];
  let cur = new Date(from + "T00:00:00Z");
  const end = new Date(to + "T00:00:00Z");
  while (cur <= end) { out.push(fmtDateUTC(cur)); cur = new Date(cur.getTime() + 86400000); }
  return out;
}
const thb = (n) => "฿" + Math.round(n || 0).toLocaleString("th-TH");
const num = (n) => Math.round(n || 0).toLocaleString("th-TH");
const pct1 = (n) => `${n >= 0 ? "+" : ""}${n.toFixed(1)}%`;
function growth(curr, prev) {
  if (!prev) return null;
  return ((curr - prev) / prev) * 100;
}
function seededRandom(seed) { let x = Math.sin(seed) * 10000; return x - Math.floor(x); }
function hashStr(s) { let h = 0; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 100000; return h; }

/* ==================================================================== */
/* Column maps for the two source sheets                                */
/* ==================================================================== */
const SALES_COLS = {
  store: ["Store"], date: ["Sales Date", "Date"], net: ["Net Sales"], gross: ["Gross Sales"],
  disc: ["Discount Value", "Discount"], qty: ["Sales Qty", "Qty"], tax: ["Tax Value", "Tax"],
  receipt: ["Receipt No.", "Receipt No", "ReceiptNo"], reason: ["Disc% Reason", "Discount Reason"],
  person: ["Sales Person Code"], sku: ["SKU Code"], desc: ["Description"], price: ["Unit Selling Price"],
  brand: ["Brand"],
};
const TENDER_PAYMENT_COLS = ["Cash", "AMEX", "ATOME", "Bangkok Bank Terminal", "KTC", "KTC Point", "KBANK", "Shopee Pay"];
const TENDER_VOUCHER_COLS = [
  "SGV", "MVCH1-ICON SIAM Mall Voucher", "MVCH2-SIAM CENTER Mall Voucher", "MVCH3-NWW MALL VOUCHER",
  "T21 Tourist THB 200 Voucher", "MVCH4-BANGKAE Mall Voucher", "ONESIAM SuperApp",
  "Central – The1 Biz Redeem Point", "CentralX THB150 E-Voucher", "General Forfeit",
  "Mega Voucher THB500", "MVCH5 THE MALL - M Point", "Mega Voucher THB100",
];
const TENDER_COLS = {
  store: ["Store Name", "Store"], date: ["Transaction Date", "Sales Date", "Date"],
  receipt: ["Receipt NO", "Receipt No.", "Receipt No"], total: ["Total Tender"],
};

/* ==================================================================== */
/* Aggregate every sub-report from one pass over raw Sheet "2026" rows   */
/* ==================================================================== */
function aggregateAllFromRows(rows) {
  if (!rows || rows.length === 0) return { error: "ไม่พบข้อมูลในไฟล์" };
  const first = rows[0];
  const k = {};
  for (const key of Object.keys(SALES_COLS)) k[key] = findKey(first, SALES_COLS[key]);
  if (!k.store || !k.date || !k.net) {
    return { error: `ไม่พบคอลัมน์ที่จำเป็น (ต้องมี Store, Sales Date, Net Sales) — พบ: ${Object.keys(first).slice(0, 8).join(", ")}...` };
  }

  const kpi = new Map(), brand = new Map(), discReason = new Map(), salesPerson = new Map(), sku = new Map(), promo = new Map();

  for (const row of rows) {
    const store = row[k.store];
    const rawDate = row[k.date];
    if (!store || rawDate === undefined || rawDate === null || rawDate === "") continue;
    const date = normalizeDateValue(rawDate);
    if (!date) continue;
    const net = Number(row[k.net]) || 0;
    const gross = k.gross ? Number(row[k.gross]) || 0 : 0;
    const disc = k.disc ? Number(row[k.disc]) || 0 : 0;
    const qty = k.qty ? Number(row[k.qty]) || 0 : 0;
    const tax = k.tax ? Number(row[k.tax]) || 0 : 0;
    const receiptNo = k.receipt ? row[k.receipt] : undefined;
    const storeKey = String(store).trim();
    const dayKey = `${storeKey}__${date}`;

    // KPI (store x date)
    if (!kpi.has(dayKey)) kpi.set(dayKey, { store: storeKey, date, netSales: 0, grossSales: 0, discount: 0, qty: 0, tax: 0, receiptSet: new Set() });
    const kd = kpi.get(dayKey);
    kd.netSales += net; kd.grossSales += gross; kd.discount += disc; kd.qty += qty; kd.tax += tax;
    if (receiptNo !== undefined) kd.receiptSet.add(receiptNo);

    // Brand (store x date x brand)
    const brandName = k.brand ? row[k.brand] : (k.desc ? String(row[k.desc] || "").trim().split(/\s+/)[0] : "OTHER");
    if (brandName) {
      const bKey = `${storeKey}__${date}__${brandName}`;
      if (!brand.has(bKey)) brand.set(bKey, { store: storeKey, date, brand: brandName, netSales: 0, grossSales: 0, qty: 0 });
      const bd = brand.get(bKey);
      bd.netSales += net; bd.grossSales += gross; bd.qty += qty;
    }

    // Discount reason (store x date x reason) — bills = distinct receipts
    const reason = k.reason ? row[k.reason] : null;
    if (reason && String(reason).trim()) {
      const rKey = `${storeKey}__${date}__${reason}`;
      if (!discReason.has(rKey)) discReason.set(rKey, { store: storeKey, date, reason: String(reason).trim(), receiptSet: new Set(), discountValue: 0 });
      const rd = discReason.get(rKey);
      if (receiptNo !== undefined) rd.receiptSet.add(receiptNo);
      rd.discountValue += disc;
      // promo bills (any reason) — dedupe by store/date/receipt
      const pKey = dayKey;
      if (!promo.has(pKey)) promo.set(pKey, { store: storeKey, date, receiptSet: new Set() });
      if (receiptNo !== undefined) promo.get(pKey).receiptSet.add(receiptNo);
    }

    // Sales person (store x date x person)
    const person = k.person ? row[k.person] : null;
    if (person && String(person).trim()) {
      const pKey2 = `${storeKey}__${date}__${person}`;
      if (!salesPerson.has(pKey2)) salesPerson.set(pKey2, { store: storeKey, date, person: String(person).trim(), netSales: 0, qty: 0 });
      const pd = salesPerson.get(pKey2);
      pd.netSales += net; pd.qty += qty;
    }

    // SKU (store x date x sku)
    const skuCode = k.sku ? row[k.sku] : null;
    if (skuCode && net !== 0) {
      const sKey = `${storeKey}__${date}__${skuCode}`;
      if (!sku.has(sKey)) sku.set(sKey, {
        store: storeKey, date, sku: String(skuCode).trim(),
        desc: k.desc ? String(row[k.desc] || "").trim() : "", brand: brandName || "OTHER",
        price: k.price ? Number(row[k.price]) || 0 : 0, qty: 0, netSales: 0,
      });
      const sd = sku.get(sKey);
      sd.qty += qty; sd.netSales += net;
    }
  }

  return {
    kpi: Array.from(kpi.values()).map((r) => ({ store: r.store, date: r.date, netSales: r2(r.netSales), grossSales: r2(r.grossSales), discount: r2(r.discount), qty: r.qty, tax: r2(r.tax), receipts: r.receiptSet.size || Math.round(r.qty) })),
    brand: Array.from(brand.values()).map((r) => ({ ...r, netSales: r2(r.netSales), grossSales: r2(r.grossSales) })),
    discReason: Array.from(discReason.values()).map((r) => ({ store: r.store, date: r.date, reason: r.reason, bills: r.receiptSet.size, discountValue: r2(r.discountValue) })),
    salesPerson: Array.from(salesPerson.values()).map((r) => ({ ...r, netSales: r2(r.netSales) })),
    sku: Array.from(sku.values()).map((r) => ({ ...r, netSales: r2(r.netSales) })),
    promo: Array.from(promo.values()).map((r) => ({ store: r.store, date: r.date, promoBills: r.receiptSet.size })),
    error: null,
  };
}
function r2(n) { return Math.round(n * 100) / 100; }

function parseTenderRows(rows) {
  if (!rows || rows.length === 0) return { error: "ไม่พบข้อมูลในไฟล์ Tender" };
  const first = rows[0];
  const storeKey = findKey(first, TENDER_COLS.store);
  const dateKey = findKey(first, TENDER_COLS.date);
  const totalKey = findKey(first, TENDER_COLS.total);
  if (!storeKey || !dateKey) return { error: `ไม่พบคอลัมน์ Store/Transaction Date ในไฟล์ Tender` };

  const payChans = TENDER_PAYMENT_COLS.map((c) => ({ label: c, key: findKey(first, [c]) })).filter((c) => c.key);
  const voucherChans = TENDER_VOUCHER_COLS.map((c) => ({ label: c, key: findKey(first, [c]) })).filter((c) => c.key);

  const map = new Map();
  for (const row of rows) {
    const store = row[storeKey];
    const rawDate = row[dateKey];
    if (!store || !rawDate) continue;
    const date = normalizeDateValue(rawDate);
    if (!date) continue;
    const dKey = `${String(store).trim()}__${date}`;
    if (!map.has(dKey)) {
      map.set(dKey, { store: String(store).trim(), date, totalTender: 0, bills: 0, payment: {}, voucher: {} });
      for (const c of payChans) map.get(dKey).payment[c.label] = 0;
      for (const c of voucherChans) map.get(dKey).voucher[c.label] = 0;
    }
    const d = map.get(dKey);
    d.totalTender += totalKey ? Number(row[totalKey]) || 0 : 0;
    d.bills += 1;
    for (const c of payChans) d.payment[c.label] += Number(row[c.key]) || 0;
    for (const c of voucherChans) d.voucher[c.label] += Number(row[c.key]) || 0;
  }
  return { records: Array.from(map.values()), error: null };
}

function parseTargetRows(rows) {
  if (!rows || rows.length === 0) return { error: "ไม่พบข้อมูลในไฟล์ Target" };
  const first = rows[0];
  const storeKey = findKey(first, ["Store"]);
  const monthKeyCol = findKey(first, ["Month", "Sales Month", "Period"]);
  const targetKey = findKey(first, ["Target", "Store Target", "Sales Target"]);
  if (!storeKey || !targetKey) return { error: `ไฟล์ Target ต้องมีคอลัมน์ Store และ Target` };
  const records = [];
  for (const row of rows) {
    const store = row[storeKey];
    if (!store) continue;
    let month = monthKeyCol ? row[monthKeyCol] : null;
    if (month instanceof Date) month = `${month.getUTCFullYear()}-${pad(month.getUTCMonth() + 1)}`;
    else if (typeof month === "string") {
      const m = month.match(/(\d{4})-(\d{1,2})/);
      month = m ? `${m[1]}-${pad(+m[2])}` : month.trim();
    } else month = "ALL";
    records.push({ store: String(store).trim(), month: month || "ALL", target: Number(row[targetKey]) || 0 });
  }
  return { records, error: null };
}

function parseNationalityRows(rows) {
  if (!rows || rows.length === 0) return { error: "ไม่พบข้อมูลในไฟล์สัดส่วนลูกค้า" };
  const first = rows[0];
  const storeKey = findKey(first, ["Store"]);
  const dateKey = findKey(first, ["Date", "Sales Date"]);
  const natKey = findKey(first, ["Nationality", "สัญชาติ"]);
  const countKey = findKey(first, ["Count", "Qty", "จำนวน"]);
  const amountKey = findKey(first, ["Amount", "Net Sales", "Sales", "ยอดซื้อ"]);
  if (!storeKey || !dateKey || !natKey) return { error: `ไฟล์สัดส่วนลูกค้าต้องมีคอลัมน์ Store, Date, Nationality` };

  const map = new Map();
  for (const row of rows) {
    const store = row[storeKey];
    const rawDate = row[dateKey];
    const nat = row[natKey];
    if (!store || !rawDate || !nat) continue;
    const date = normalizeDateValue(rawDate);
    if (!date) continue;
    const storeStr = String(store).trim();
    const natStr = String(nat).trim();
    const key = `${storeStr}__${date}__${natStr}`;
    if (!map.has(key)) map.set(key, { store: storeStr, date, nationality: natStr, count: 0, amount: 0 });
    const o = map.get(key);
    o.count += countKey ? Number(row[countKey]) || 0 : 1;
    o.amount += amountKey ? Number(row[amountKey]) || 0 : 0;
  }
  return { records: Array.from(map.values()), error: null };
}

function exportToExcel(filename, sheetsData) {
  const wb = XLSX.utils.book_new();
  sheetsData.forEach(({ name, rows }) => {
    const ws = XLSX.utils.json_to_sheet(rows.length ? rows : [{ "ไม่มีข้อมูล": "" }]);
    XLSX.utils.book_append_sheet(wb, ws, name.slice(0, 31));
  });
  XLSX.writeFile(wb, filename);
}

function rwNumClean(v) {
  if (v === null || v === undefined || v === "") return 0;
  const n = parseFloat(String(v).replace(/,/g, "").replace(/฿/g, ""));
  return isNaN(n) ? 0 : n;
}
function rwPctClean(v) {
  if (v === null || v === undefined || v === "") return null;
  const n = parseFloat(String(v).replace(/%/g, "").replace(/,/g, ""));
  return isNaN(n) ? null : n;
}
function rwFindHeaderRow(rows, requiredCols) {
  for (let i = 0; i < rows.length; i++) {
    const row = (rows[i] || []).map((c) => String(c || "").trim().toLowerCase());
    if (requiredCols.every((rc) => row.includes(rc.toLowerCase()))) return i;
  }
  return -1;
}
function rwFindColFlexible(header, candidates) {
  const norm = (s) => String(s || "").toLowerCase().replace(/\.$/, "").trim();
  const normalizedHeader = header.map(norm);
  for (const cand of candidates) {
    const idx = normalizedHeader.indexOf(norm(cand));
    if (idx !== -1) return idx;
  }
  return -1;
}
function rwCellToISODate(v) {
  if (v instanceof Date && !isNaN(v.getTime())) {
    return `${v.getUTCFullYear()}-${String(v.getUTCMonth() + 1).padStart(2, "0")}-${String(v.getUTCDate()).padStart(2, "0")}`;
  }
  if (typeof v === "number") {
    // Excel serial date (days since 1899-12-30)
    const ms = Math.round((v - 25569) * 86400 * 1000);
    const d = new Date(ms);
    if (!isNaN(d.getTime())) return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
  }
  const s = String(v || "").trim();
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`;
  return null;
}
function rwParseWorkbook(wb) {
  const leadership = [];
  const transactions = [];
  let periodLabel = "";

  for (const sheetName of wb.SheetNames) {
    const sheet = wb.Sheets[sheetName];
    const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, raw: false });
    const rowsRaw = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: null, raw: true });

    const lIdx = rwFindHeaderRow(rows, ["Store Code", "Employee", "Job Title"]);
    if (lIdx !== -1) {
      const header = rows[lIdx].map((c) => String(c || "").trim());
      const col = (name) => header.findIndex((h) => h.toLowerCase() === name.toLowerCase());
      const c = {
        store: col("Store Code"), emp: col("Employee"), job: col("Job Title"),
        seg: col("# Seg"), segOk: col("Success Segments"), segPct: col("% Success"),
        salesActual: col("Sales Actual"), salesVar: col("Sales Var"), salesTargetPct: col("Sales % Target"),
        salesTrans: col("Sales Trans"), convPct: col("Conv %"), atv: col("ATV"), upt: col("UPT"), visitValue: col("Visit Value"),
      };
      for (let j = Math.max(0, lIdx - 6); j < lIdx; j++) {
        const text = (rows[j] || []).map((cell) => String(cell || "")).join(" ");
        const m = text.match(/\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\s*(?:-|to|–|—)\s*\d{1,2}[/-]\d{1,2}[/-]\d{2,4}/i);
        if (m) periodLabel = m[0];
      }
      for (let i = lIdx + 1; i < rows.length; i++) {
        const row = rows[i] || [];
        const storeCode = String(row[c.store] || "").trim();
        const employee = String(row[c.emp] || "").trim();
        if (!storeCode || !employee) continue; // skip blank/separator rows but keep scanning the rest of the sheet
        leadership.push({
          storeCode, employee, jobTitle: String(row[c.job] || "").trim(),
          segTotal: rwNumClean(row[c.seg]), segSuccess: rwNumClean(row[c.segOk]), successPct: rwPctClean(row[c.segPct]),
          salesActual: rwNumClean(row[c.salesActual]), salesVar: rwNumClean(row[c.salesVar]), salesTargetPct: rwPctClean(row[c.salesTargetPct]),
          salesTrans: rwNumClean(row[c.salesTrans]), convPct: rwPctClean(row[c.convPct]), atv: rwNumClean(row[c.atv]), upt: rwNumClean(row[c.upt]), visitValue: rwNumClean(row[c.visitValue]),
          isStoreTotal: employee.toLowerCase() === "store total",
          period: periodLabel,
        });
      }
    }

    const tIdx = rwFindHeaderRow(rows, ["Store", "Brand", "SKU Code"]);
    if (tIdx !== -1) {
      const header = rows[tIdx].map((c) => String(c || "").trim());
      const c = {
        store: rwFindColFlexible(header, ["Store"]),
        brand: rwFindColFlexible(header, ["Brand"]),
        date: rwFindColFlexible(header, ["Sales Date", "Sale Date"]),
        sku: rwFindColFlexible(header, ["SKU Code", "SKU"]),
        personCode: rwFindColFlexible(header, ["Sales Person Code", "Sale Person Code"]),
        person: rwFindColFlexible(header, ["Sales Person", "Sale Person"]),
        rType: rwFindColFlexible(header, ["Receipt Type"]),
        rNo: rwFindColFlexible(header, ["Receipt No.", "Receipt No"]),
        qty: rwFindColFlexible(header, ["Sales Qty", "Sale Qty", "Sale QTY", "Sales QTY"]),
        net: rwFindColFlexible(header, ["Net Sales", "Net Sale"]),
      };
      const seenRows = new Set(); // dedupe exact-duplicate bill lines (same receipt+sku+qty repeated in the source file)
      for (let i = tIdx + 1; i < rows.length; i++) {
        const row = rows[i] || [];
        const rawRow = rowsRaw[i] || [];
        const store = String(row[c.store] || "").trim();
        if (!store) continue;
        const receiptNo = String(row[c.rNo] || "").trim();
        const sku = String(row[c.sku] || "").trim();
        const salesDate = rwCellToISODate(rawRow[c.date]) || String(row[c.date] || "").trim();
        const qty = rwNumClean(row[c.qty]);
        const netSales = rwNumClean(row[c.net]);
        const dedupeKey = `${store}|${receiptNo}|${sku}|${salesDate}|${qty}|${netSales}`;
        if (seenRows.has(dedupeKey)) continue; // exact duplicate bill line — skip
        seenRows.add(dedupeKey);
        transactions.push({
          store, brand: String(row[c.brand] || "").trim(), salesDate, sku,
          salesPersonCode: String(row[c.personCode] || "").trim(), salesPerson: String(row[c.person] || "").trim(),
          receiptType: String(row[c.rType] || "").trim(), receiptNo,
          qty, netSales,
        });
      }
    }
  }
  return { leadership, transactions, periodLabel };
}
function rwAsicsIncentive(transactions, rate) {
  const map = new Map();
  transactions.forEach((t) => {
    if (!t.brand.toUpperCase().includes("ASICS")) return;
    const key = t.salesPersonCode || t.salesPerson || "-";
    if (!key || key === "-") return;
    if (!map.has(key)) map.set(key, { key, salesPerson: t.salesPerson || t.salesPersonCode, store: t.store, qty: 0, incentive: 0 });
    const g = map.get(key);
    g.qty += t.qty;
    g.incentive += t.qty * rate;
  });
  return Array.from(map.values()).sort((a, b) => b.incentive - a.incentive);
}

const RW_CHUNK_SIZE = 1500; // keep each saved piece small/reliable regardless of total dataset size
async function saveChunked(prefix, rows) {
  const chunks = [];
  for (let i = 0; i < rows.length; i += RW_CHUNK_SIZE) chunks.push(rows.slice(i, i + RW_CHUNK_SIZE));
  let prevCount = 0;
  try { const metaRaw = await window.storage.get(`${prefix}:meta`, true); if (metaRaw?.value) prevCount = JSON.parse(metaRaw.value).count || 0; } catch (e) {}
  for (let i = 0; i < chunks.length; i++) {
    try { await window.storage.set(`${prefix}:chunk${i}`, JSON.stringify(chunks[i]), true); } catch (e) {}
  }
  for (let i = chunks.length; i < prevCount; i++) {
    try { await window.storage.delete(`${prefix}:chunk${i}`, true); } catch (e) {}
  }
  try { await window.storage.set(`${prefix}:meta`, JSON.stringify({ count: chunks.length, total: rows.length }), true); } catch (e) {}
}
async function loadChunked(prefix) {
  try {
    const metaRaw = await window.storage.get(`${prefix}:meta`, true);
    if (metaRaw?.value) {
      const meta = JSON.parse(metaRaw.value);
      let out = [];
      for (let i = 0; i < meta.count; i++) {
        try { const c = await window.storage.get(`${prefix}:chunk${i}`, true); if (c?.value) out = out.concat(JSON.parse(c.value)); } catch (e) {}
      }
      return out;
    }
  } catch (e) {}
  try { const v = await window.storage.get(prefix, true); if (v?.value) return JSON.parse(v.value); } catch (e) {}
  return [];
}

const UPLOAD_META_PREFIX = "upload:meta:";
async function recordUploadTimestamp(datasetKey) {
  try { await window.storage.set(UPLOAD_META_PREFIX + datasetKey, JSON.stringify({ uploadedAt: new Date().toISOString() }), true); } catch (e) {}
}
function fmtUploadedAt(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d.getTime())) return null;
  const dd = String(d.getDate()).padStart(2, "0"), mm = String(d.getMonth() + 1).padStart(2, "0"), yyyy = d.getFullYear();
  const hh = String(d.getHours()).padStart(2, "0"), min = String(d.getMinutes()).padStart(2, "0");
  return `${dd}/${mm}/${yyyy} ${hh}:${min}`;
}

function mergeByKey(base, incoming, keyFn) {
  const map = new Map(base.map((r) => [keyFn(r), r]));
  for (const r of incoming) map.set(keyFn(r), r);
  return Array.from(map.values());
}

function scaleDemoRecords(records, numericFields) {
  return records.map((r) => {
    const seed = hashStr(JSON.stringify(r)) + 1;
    const factor = 0.78 + seededRandom(seed) * 0.22;
    const out = { ...r, date: shiftYearDate(r.date, -1) };
    for (const f of numericFields) out[f] = Math.round((r[f] || 0) * factor * 100) / 100;
    return out;
  });
}

/* ==================================================================== */
/* Query helpers                                                         */
/* ==================================================================== */
function inRange(store, storeFilter, date, dateSet) {
  if (storeFilter !== "ALL" && store !== storeFilter) return false;
  return dateSet.has(date);
}
function sumKpi(records, storeFilter, dates) {
  const dateSet = new Set(dates);
  let netSales = 0, grossSales = 0, discount = 0, qty = 0, tax = 0, receipts = 0, found = false;
  for (const r of records) {
    if (!inRange(r.store, storeFilter, r.date, dateSet)) continue;
    found = true;
    netSales += r.netSales; grossSales += r.grossSales; discount += r.discount; qty += r.qty; tax += r.tax; receipts += r.receipts;
  }
  return { netSales, grossSales, discount, qty, tax, receipts, found };
}
function groupSum(records, storeFilter, dates, groupField, sumFields) {
  const dateSet = new Set(dates);
  const out = new Map();
  for (const r of records) {
    if (!inRange(r.store, storeFilter, r.date, dateSet)) continue;
    const gk = r[groupField];
    if (!out.has(gk)) {
      const init = { [groupField]: gk };
      for (const f of sumFields) init[f] = 0;
      out.set(gk, init);
    }
    const o = out.get(gk);
    for (const f of sumFields) o[f] += r[f] || 0;
  }
  return Array.from(out.values());
}

/* ==================================================================== */
/* Small UI atoms                                                        */
/* ==================================================================== */
function GrowthBadge({ value }) {
  if (value === null || value === undefined) return <span className="badge badge-flat">ไม่มีข้อมูลเทียบ</span>;
  const up = value > 0.05, down = value < -0.05;
  const hot = value >= 20;
  const cls = up ? "badge badge-pos" : down ? "badge badge-neg" : "badge badge-flat";
  const Icon = hot ? Flame : up ? TrendingUp : down ? TrendingDown : Minus;
  return <span className={cls}><Icon size={13} strokeWidth={2.5} className={hot ? "badge-flame" : ""} />{pct1(value)}</span>;
}
function MiniStat({ label, value, sub, progress, badge }) {
  return (
    <div className="mini-stat">
      <div className="mini-stat-label">{label}{badge}</div>
      <div className="mini-stat-value">{value}</div>
      {sub && <div className="mini-stat-sub">{sub}</div>}
      {progress !== undefined && progress !== null && (
        <div className="mini-stat-bar-track">
          <div className="mini-stat-bar-fill" style={{ width: `${Math.min(100, Math.max(0, progress))}%` }} />
          {progress >= 100 && <span className="mini-stat-bar-star">★</span>}
        </div>
      )}
    </div>
  );
}

/* Draggable widget shell */
function WidgetShell({ id, title, icon, onDragStart, onDragOver, onDrop, onHide, dragging, scale, onScaleChange, children }) {
  const dragState = useRef(null);

  const onResizeStart = (e) => {
    e.preventDefault();
    e.stopPropagation();
    dragState.current = { startX: e.clientX, startScale: scale || 1 };
    const onMove = (ev) => {
      if (!dragState.current) return;
      const delta = ev.clientX - dragState.current.startX;
      const next = Math.min(1.6, Math.max(0.55, dragState.current.startScale + delta / 260));
      onScaleChange(id, Math.round(next * 100) / 100);
    };
    const onUp = () => {
      dragState.current = null;
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
  };

  const pct = Math.round((scale || 1) * 100);

  return (
    <div
      className={`widget${dragging ? " widget-dragging" : ""}`}
      draggable
      onDragStart={(e) => onDragStart(e, id)}
      onDragOver={(e) => onDragOver(e, id)}
      onDrop={(e) => onDrop(e, id)}
    >
      <div className="widget-head">
        <span className="widget-drag no-print"><GripVertical size={15} /></span>
        <span className="widget-icon">{icon}</span>
        <span className="widget-title">{title}</span>
        {pct !== 100 && <span className="widget-scale-pct no-print">{pct}%</span>}
        <button className="widget-hide no-print" onClick={() => onHide(id)} title="ซ่อน widget นี้"><X size={14} /></button>
      </div>
      <div className="widget-body-wrap">
        <div className="widget-body" style={{ zoom: scale || 1 }}>{children}</div>
      </div>
      <div
        className="widget-resize-handle no-print"
        onMouseDown={onResizeStart}
        onDoubleClick={() => onScaleChange(id, 1)}
        title="ลากเพื่อขยาย/ย่อ · ดับเบิลคลิกเพื่อรีเซ็ต"
      >
        <svg width="11" height="11" viewBox="0 0 11 11"><path d="M9 1L1 9M9 5L5 9M9 9L9 9" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" /></svg>
      </div>
    </div>
  );
}

/* Collapsible filter dropdown — shows an active-indicator icon only when a custom filter is engaged */
function FilterDropdown({ active, children, label = "ตัวกรอง" }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="filter-dd no-print">
      <button type="button" className={`filter-dd-toggle${active ? " filter-dd-active" : ""}`} onClick={() => setOpen((o) => !o)}>
        <SlidersHorizontal size={12} />
        <span>{label}</span>
        {active && <span className="filter-dd-dot" title="มีตัวกรองที่ตั้งค่าไว้" />}
        <ChevronDown size={12} className={open ? "filter-dd-chev-open" : ""} />
      </button>
      {open && <div className="filter-dd-panel">{children}</div>}
    </div>
  );
}

/* ==================================================================== */
/* Fixed top section: daily reflection                                   */
/* ==================================================================== */
function ReflectionBar({ ctx }) {
  const key = `reflect:${ctx.store}:${ctx.from}:${ctx.to}`;
  const [fail, setFail] = useState("");
  const [win, setWin] = useState("");
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    (async () => {
      setSaved(false);
      try {
        const v = await window.storage.get(key, true);
        if (v?.value) { const parsed = JSON.parse(v.value); setFail(parsed.fail || ""); setWin(parsed.win || ""); setSaved(true); }
        else { setFail(""); setWin(""); }
      } catch (e) { setFail(""); setWin(""); }
    })();
  }, [key]);

  const save = async () => {
    try { await window.storage.set(key, JSON.stringify({ fail, win, savedAt: new Date().toISOString() }), true); setSaved(true); ctx.showToast("success", "บันทึกสรุปวันนี้แล้ว"); }
    catch (e) { ctx.showToast("error", "บันทึกไม่สำเร็จ"); }
  };

  return (
    <div className="reflect-bar no-print-loose">
      <div className="reflect-col">
        <div className="reflect-label"><Frown size={15} /> 1 เรื่องที่ยังไม่สำเร็จวันนี้ + เพราะอะไร</div>
        <textarea value={fail} onChange={(e) => { setFail(e.target.value); setSaved(false); }} placeholder="เช่น: ยอดพลาดเป้าเพราะสต็อกไซส์ยอดนิยมขาด..." />
      </div>
      <div className="reflect-col">
        <div className="reflect-label"><Smile size={15} /> 1 เรื่องที่สำเร็จวันนี้ + เพราะอะไร</div>
        <textarea value={win} onChange={(e) => { setWin(e.target.value); setSaved(false); }} placeholder="เช่น: ปิดยอดคู่ ATV สูงเพราะทีมแนะนำสินค้าคู่ได้ดี..." />
      </div>
      <button className="btn btn-primary reflect-save no-print" onClick={save} disabled={saved}>
        <Save size={14} /> {saved ? "บันทึกแล้ว" : "บันทึก"}
      </button>
    </div>
  );
}

/* ==================================================================== */
/* Fixed KPI block: Store Target / MTD / %Hit / ATV / IPT / CR           */
/* ==================================================================== */
/* ==================================================================== */
/* Achievement badges — playful reward strip for hitting targets         */
/* ==================================================================== */
function AchievementBadges({ ctx }) {
  const monthStart = ctx.to.slice(0, 8) + "01";
  const mtdDates = useMemo(() => dateRangeArray(monthStart, ctx.to), [monthStart, ctx.to]);
  const mtd = useMemo(() => sumKpi(ctx.data.kpi, ctx.store, mtdDates), [ctx.data.kpi, ctx.store, mtdDates]);
  const targetForMonth = useMemo(() => {
    const mo = monthKey(ctx.to);
    const rows = ctx.targets.filter((t) => (ctx.store === "ALL" || t.store === ctx.store) && (t.month === mo || t.month === "ALL"));
    if (rows.length === 0) return null;
    return rows.reduce((s, r) => s + r.target, 0);
  }, [ctx.targets, ctx.store, ctx.to]);
  const hitPct = targetForMonth ? (mtd.netSales / targetForMonth) * 100 : null;

  const cur = ctx.curTotals, ly = ctx.lyTotals;
  const netGrowth = ctx.hasLY ? growth(cur.netSales, ly.netSales) : null;
  const avgBasketCur = cur.receipts ? cur.netSales / cur.receipts : 0;
  const avgBasketLY = ly.receipts ? ly.netSales / ly.receipts : 0;
  const basketGrowth = ctx.hasLY ? growth(avgBasketCur, avgBasketLY) : null;
  const discRate = cur.grossSales ? (cur.discount / cur.grossSales) * 100 : null;

  const badges = [
    { key: "target", icon: <Trophy size={16} />, label: "Target Hit", hint: "MTD ถึงเป้าเดือนนี้", earned: hitPct !== null && hitPct >= 100 },
    { key: "growth", icon: <Flame size={16} />, label: "Growth Star", hint: "ยอดขายโตกว่าปีก่อน ≥10%", earned: netGrowth !== null && netGrowth >= 10 },
    { key: "basket", icon: <Star size={16} />, label: "Big Basket", hint: "ยอดเฉลี่ยต่อบิลโตกว่าปีก่อน", earned: basketGrowth !== null && basketGrowth > 0 },
    { key: "margin", icon: <Zap size={16} />, label: "Sharp Margin", hint: "อัตราส่วนลดเฉลี่ย ≤15%", earned: discRate !== null && discRate <= 15 },
  ];
  const earnedCount = badges.filter((b) => b.earned).length;

  return (
    <div className="badge-strip">
      <div className="badge-strip-head">
        <span>ความสำเร็จของช่วงนี้</span>
        <span className="badge-strip-count">{earnedCount}/{badges.length}</span>
      </div>
      <div className="badge-strip-row">
        {badges.map((b) => (
          <div key={b.key} className={`achieve-badge${b.earned ? " achieve-earned" : ""}`} title={b.hint}>
            <span className="achieve-icon">{b.icon}</span>
            <span className="achieve-label">{b.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function FixedKpiBlock({ ctx }) {
  const monthStart = ctx.to.slice(0, 8) + "01";
  const mtdDates = useMemo(() => dateRangeArray(monthStart, ctx.to), [monthStart, ctx.to]);
  const mtd = useMemo(() => sumKpi(ctx.data.kpi, ctx.store, mtdDates), [ctx.data.kpi, ctx.store, mtdDates]);

  const targetForMonth = useMemo(() => {
    const mo = monthKey(ctx.to);
    const rows = ctx.targets.filter((t) => (ctx.store === "ALL" || t.store === ctx.store) && (t.month === mo || t.month === "ALL"));
    if (rows.length === 0) return null;
    return rows.reduce((s, r) => s + r.target, 0);
  }, [ctx.targets, ctx.store, ctx.to]);

  const hitPct = targetForMonth ? (mtd.netSales / targetForMonth) * 100 : null;
  const cur = ctx.curTotals;
  const netWoTax = cur.netSales - cur.tax;
  const atv = cur.receipts ? netWoTax / cur.receipts : 0;
  const ipt = cur.receipts ? cur.qty / cur.receipts : 0;
  const cr = ctx.footfall ? (cur.receipts / ctx.footfall) * 100 : null;

  return (
    <div className="fixed-kpi-grid">
      <MiniStat label="Store Target (เดือนนี้)" value={targetForMonth ? thb(targetForMonth) : "ยังไม่มีข้อมูล"} sub={targetForMonth ? null : "อัปโหลดไฟล์ Target"} />
      <MiniStat label="MTD Sale" value={thb(mtd.netSales)} sub={`ถึงวันที่ ${ctx.to}`} />
      <MiniStat label="% Hit" value={hitPct !== null ? `${hitPct.toFixed(1)}%` : "—"} sub={hitPct !== null ? (hitPct >= 100 ? "🏆 ถึงเป้าแล้ว!" : `ขาดอีก ${thb(Math.max(0, targetForMonth - mtd.netSales))}`) : null} progress={hitPct} badge={hitPct !== null && hitPct >= 100 ? <Trophy size={13} className="mini-stat-trophy" /> : null} />
      <MiniStat label="ATV (ยอดเฉลี่ย/บิล)" value={thb(atv)} sub={`${num(cur.receipts)} บิล ในช่วงที่เลือก`} />
      <MiniStat label="IPT (ชิ้น/บิล)" value={ipt.toFixed(2)} sub={`${num(cur.qty)} ชิ้น`} />
      <MiniStat label="CR (Conversion)" value={cr !== null ? `${cr.toFixed(1)}%` : "กรอก Footfall"} sub={ctx.footfall ? `Footfall ${num(ctx.footfall)}` : null} />
    </div>
  );
}

/* ==================================================================== */
/* Generic text-note widget (Store Comment / Action Plan)                */
/* ==================================================================== */
function TextNoteWidget({ ctx, storagePrefix, placeholder, historyTitle }) {
  const noteKey = `${storagePrefix}:${ctx.store}:${ctx.from}:${ctx.to}`;
  const [text, setText] = useState("");
  const [items, setItems] = useState([]);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    try {
      const list = await window.storage.list(`${storagePrefix}:`, true);
      const keys = list?.keys || [];
      const out = [];
      for (const kk of keys) {
        try { const v = await window.storage.get(kk, true); if (v?.value) out.push({ key: kk, ...JSON.parse(v.value) }); } catch (e) {}
      }
      out.sort((a, b) => (b.savedAt || "").localeCompare(a.savedAt || ""));
      setItems(out);
    } catch (e) {}
  }, [storagePrefix]);

  useEffect(() => { load(); }, [load]);

  const save = async () => {
    if (!text.trim()) return;
    setSaving(true);
    try {
      await window.storage.set(noteKey, JSON.stringify({ store: ctx.store, from: ctx.from, to: ctx.to, text: text.trim(), savedAt: new Date().toISOString() }), true);
      setText(""); ctx.showToast("success", "บันทึกแล้ว"); load();
    } catch (e) { ctx.showToast("error", "บันทึกไม่สำเร็จ"); }
    setSaving(false);
  };

  const current = items.find((n) => n.key === noteKey);

  return (
    <div>
      {current && <div style={{ marginBottom: ".5rem" }}><span className="current-note-flag">มีบันทึกล่าสุดสำหรับช่วงนี้</span></div>}
      <textarea placeholder={placeholder} value={text} onChange={(e) => setText(e.target.value)} />
      <div style={{ display: "flex", justifyContent: "flex-end", marginTop: ".5rem" }}>
        <button className="btn btn-primary no-print" onClick={save} disabled={saving || !text.trim()}><Save size={14} /> บันทึก</button>
      </div>
      {items.length > 0 && (
        <div style={{ marginTop: ".8rem", paddingTop: ".7rem", borderTop: "1px solid var(--line)" }}>
          <div className="panel-title">{historyTitle}</div>
          {items.slice(0, 6).map((n) => (
            <div className="note-item" key={n.key}>
              <div className="note-meta"><b>{n.store === "ALL" ? "ทุกสาขา" : n.store}</b><span>{n.from} – {n.to}</span><span>· {new Date(n.savedAt).toLocaleString("th-TH")}</span></div>
              <div className="note-text">{n.text}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/* ==================================================================== */
/* Trend chart widget                                                    */
/* ==================================================================== */
function TrendWidget({ ctx }) {
  const [customRange, setCustomRange] = useState(false);
  const [tFrom, setTFrom] = useState(ctx.from);
  const [tTo, setTTo] = useState(ctx.to);
  useEffect(() => { if (!customRange) { setTFrom(ctx.from); setTTo(ctx.to); } }, [ctx.from, ctx.to, customRange]);

  const dates = useMemo(() => dateRangeArray(tFrom, tTo), [tFrom, tTo]);
  const lyDates = useMemo(() => dates.map((d) => shiftYearDate(d, -1)), [dates]);

  const trendData = useMemo(() => dates.map((d, i) => {
    const c = sumKpi(ctx.data.kpi, ctx.store, [d]);
    const l = sumKpi(ctx.lyData.kpi, ctx.store, [lyDates[i]]);
    return { label: d.slice(5), "ปีนี้": Math.round(c.netSales), "ปีก่อน": l.found ? Math.round(l.netSales) : null };
  }), [dates, lyDates, ctx.data.kpi, ctx.lyData.kpi, ctx.store]);

  return (
    <div>
      <FilterDropdown active={customRange}>
        <label><input type="checkbox" checked={customRange} onChange={(e) => setCustomRange(e.target.checked)} /> ช่วงวันที่ของตัวเอง</label>
        {customRange && (<>
          <input type="date" value={tFrom} onChange={(e) => setTFrom(e.target.value)} />
          <input type="date" value={tTo} min={tFrom} onChange={(e) => setTTo(e.target.value)} />
        </>)}
      </FilterDropdown>
      {trendData.length > 0 ? (
        <ResponsiveContainer width="100%" height={240}>
          <LineChart data={trendData} margin={{ top: 4, right: 12, left: -12, bottom: 0 }}>
            <CartesianGrid stroke="#EEEEEA" vertical={false} />
            <XAxis dataKey="label" tick={{ fontSize: 11, fill: "#6B6B66" }} axisLine={{ stroke: "#E6E6E2" }} tickLine={false} />
            <YAxis tick={{ fontSize: 11, fill: "#6B6B66" }} axisLine={false} tickLine={false} tickFormatter={(v) => (v >= 1000 ? `${(v / 1000).toFixed(0)}k` : v)} />
            <Tooltip formatter={(v) => (v === null ? "ไม่มีข้อมูล" : thb(v))} contentStyle={{ fontSize: 12, borderRadius: 8, border: "1px solid #E6E6E2" }} />
            <Line type="monotone" dataKey="ปีนี้" stroke="#111111" strokeWidth={2.4} dot={{ r: 3 }} connectNulls />
            <Line type="monotone" dataKey="ปีก่อน" stroke="#FFC800" strokeWidth={2.2} strokeDasharray="4 3" dot={{ r: 2.5, fill: "#FFC800" }} connectNulls />
          </LineChart>
        </ResponsiveContainer>
      ) : <div className="empty-hint">เลือกช่วงวันที่เพื่อดูกราฟ</div>}
    </div>
  );
}

/* ==================================================================== */
/* Sales overview KPI cards                                              */
/* ==================================================================== */
function SalesOverviewWidget({ ctx }) {
  const cur = ctx.curTotals, ly = ctx.lyTotals, hasLY = ly.found;
  const avgBasketCur = cur.receipts ? cur.netSales / cur.receipts : 0;
  const avgBasketLY = ly.receipts ? ly.netSales / ly.receipts : 0;
  const discRate = cur.grossSales ? (cur.discount / cur.grossSales) * 100 : 0;
  return (
    <div className="kpi-grid">
      <div className="kpi-card"><div className="kpi-label">ยอดขายสุทธิ (Net Sales)</div><div className="kpi-value">{thb(cur.netSales)}</div><div className="kpi-foot"><GrowthBadge value={hasLY ? growth(cur.netSales, ly.netSales) : null} />{hasLY && <span className="kpi-sub">ปีก่อน {thb(ly.netSales)}</span>}</div></div>
      <div className="kpi-card"><div className="kpi-label">ยอดขายรวม (Gross)</div><div className="kpi-value">{thb(cur.grossSales)}</div><div className="kpi-foot"><GrowthBadge value={hasLY ? growth(cur.grossSales, ly.grossSales) : null} /></div></div>
      <div className="kpi-card"><div className="kpi-label">จำนวนชิ้นที่ขาย</div><div className="kpi-value">{num(cur.qty)}</div><div className="kpi-foot"><GrowthBadge value={hasLY ? growth(cur.qty, ly.qty) : null} /></div></div>
      <div className="kpi-card"><div className="kpi-label">ยอดเฉลี่ยต่อบิล</div><div className="kpi-value">{thb(avgBasketCur)}</div><div className="kpi-foot"><GrowthBadge value={hasLY ? growth(avgBasketCur, avgBasketLY) : null} /><span className="kpi-sub">{num(cur.receipts)} บิล</span></div></div>
      <div className="kpi-card"><div className="kpi-label">อัตราส่วนลดเฉลี่ย</div><div className="kpi-value">{discRate.toFixed(1)}%</div><div className="kpi-foot"><span className="kpi-sub">{thb(cur.discount)} ส่วนลดรวม</span></div></div>
    </div>
  );
}

/* ==================================================================== */
/* Store / date breakdown table                                          */
/* ==================================================================== */
function BreakdownWidget({ ctx }) {
  const rows = useMemo(() => {
    if (ctx.store === "ALL") {
      return ctx.stores.map((s) => {
        const c = sumKpi(ctx.data.kpi, s, ctx.dates);
        const l = sumKpi(ctx.lyData.kpi, s, ctx.lyDates);
        return { key: s, label: s, netSales: c.netSales, receipts: c.receipts, g: l.found ? growth(c.netSales, l.netSales) : null };
      }).sort((a, b) => b.netSales - a.netSales);
    }
    return ctx.dates.map((d, i) => {
      const c = sumKpi(ctx.data.kpi, ctx.store, [d]);
      const l = sumKpi(ctx.lyData.kpi, ctx.store, [ctx.lyDates[i]]);
      return { key: d, label: d, netSales: c.netSales, receipts: c.receipts, g: l.found ? growth(c.netSales, l.netSales) : null };
    });
  }, [ctx.store, ctx.stores, ctx.dates, ctx.lyDates, ctx.data.kpi, ctx.lyData.kpi]);

  return (
    <table className="data-table">
      <thead><tr><th>{ctx.store === "ALL" ? "สาขา" : "วันที่"}</th><th className="num">ยอดขายสุทธิ</th><th className="num">จำนวนบิล</th><th className="num">เติบโต YoY</th></tr></thead>
      <tbody>{rows.map((r) => (<tr key={r.key}><td>{r.label}</td><td className="num">{thb(r.netSales)}</td><td className="num">{num(r.receipts)}</td><td className="num"><GrowthBadge value={r.g} /></td></tr>))}</tbody>
    </table>
  );
}

/* ==================================================================== */
/* Brand revenue widget                                                  */
/* ==================================================================== */
function BrandWidget({ ctx }) {
  const [selected, setSelected] = useState(null); // null = all

  const [customStore, setCustomStore] = useState(false);
  const [brStore, setBrStore] = useState(ctx.store);
  useEffect(() => { if (!customStore) setBrStore(ctx.store); }, [ctx.store, customStore]);

  const [customRange, setCustomRange] = useState(false);
  const [brFrom, setBrFrom] = useState(ctx.from);
  const [brTo, setBrTo] = useState(ctx.to);
  useEffect(() => { if (!customRange) { setBrFrom(ctx.from); setBrTo(ctx.to); } }, [ctx.from, ctx.to, customRange]);

  const dates = useMemo(() => dateRangeArray(brFrom, brTo), [brFrom, brTo]);
  const lyDates = useMemo(() => dates.map((d) => shiftYearDate(d, -1)), [dates]);

  const allBrandRows = useMemo(() => {
    const rows = groupSum(ctx.data.brand, brStore, dates, "brand", ["netSales", "grossSales", "qty"]);
    return rows.sort((a, b) => b.grossSales - a.grossSales);
  }, [ctx.data.brand, brStore, dates]);

  const lyBrandRows = useMemo(() => groupSum(ctx.lyData.brand, brStore, lyDates, "brand", ["netSales", "grossSales", "qty"]), [ctx.lyData.brand, brStore, lyDates]);
  const lyMap = useMemo(() => new Map(lyBrandRows.map((r) => [r.brand, r])), [lyBrandRows]);

  const totalGross = allBrandRows.reduce((s, r) => s + r.grossSales, 0);
  const visibleRows = selected ? allBrandRows.filter((r) => selected.has(r.brand)) : allBrandRows;
  const filterActive = customStore || customRange || selected !== null;

  return (
    <div>
      <FilterDropdown active={filterActive}>
        <label><input type="checkbox" checked={customStore} onChange={(e) => setCustomStore(e.target.checked)} /> เลือกสาขาของตัวเอง</label>
        {customStore && (
          <select value={brStore} onChange={(e) => setBrStore(e.target.value)} style={{ width: "auto" }}>
            <option value="ALL">ทุกสาขา</option>
            {ctx.stores.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        )}
        <label><input type="checkbox" checked={customRange} onChange={(e) => setCustomRange(e.target.checked)} /> ช่วงวันที่ของตัวเอง</label>
        {customRange && (<>
          <input type="date" value={brFrom} onChange={(e) => setBrFrom(e.target.value)} />
          <input type="date" value={brTo} min={brFrom} onChange={(e) => setBrTo(e.target.value)} />
        </>)}
        <div className="chip-row">
          {allBrandRows.slice(0, 16).map((r) => {
            const active = !selected || selected.has(r.brand);
            return (
              <button key={r.brand} className={`chip${active ? " chip-active" : ""}`}
                onClick={() => setSelected((prev) => {
                  const s = prev ? new Set(prev) : new Set(allBrandRows.map((x) => x.brand));
                  if (s.has(r.brand)) s.delete(r.brand); else s.add(r.brand);
                  return s;
                })}>{r.brand}</button>
            );
          })}
          {selected && <button className="chip chip-reset" onClick={() => setSelected(null)}>แสดงทั้งหมด</button>}
          {allBrandRows.length > 0 && (!selected || selected.size > 0) && <button className="chip chip-clear" onClick={() => setSelected(new Set())}>ล้างทั้งหมด</button>}
        </div>
      </FilterDropdown>
      <table className="data-table">
        <thead><tr><th>แบรนด์</th><th className="num">ยอดขาย (Gross)</th><th className="num">% ยอดรวม</th><th className="num">เติบโต YoY</th></tr></thead>
        <tbody>
          {visibleRows.map((r) => {
            const ly = lyMap.get(r.brand);
            return (
              <tr key={r.brand}>
                <td>{r.brand}</td>
                <td className="num">{thb(r.grossSales)}</td>
                <td className="num">{totalGross ? ((r.grossSales / totalGross) * 100).toFixed(1) : "0.0"}%</td>
                <td className="num"><GrowthBadge value={ly ? growth(r.grossSales, ly.grossSales) : null} /></td>
              </tr>
            );
          })}
          {visibleRows.length === 0 && <tr><td colSpan={4} className="empty-hint">ไม่มีข้อมูล</td></tr>}
        </tbody>
      </table>
    </div>
  );
}

/* ==================================================================== */
/* SKU bestseller widget                                                 */
/* ==================================================================== */
function SkuWidget({ ctx }) {
  const [customRange, setCustomRange] = useState(false);
  const [skuFrom, setSkuFrom] = useState(ctx.from);
  const [skuTo, setSkuTo] = useState(ctx.to);
  useEffect(() => { if (!customRange) { setSkuFrom(ctx.from); setSkuTo(ctx.to); } }, [ctx.from, ctx.to, customRange]);

  const [customStore, setCustomStore] = useState(false);
  const [skuStore, setSkuStore] = useState(ctx.store);
  useEffect(() => { if (!customStore) setSkuStore(ctx.store); }, [ctx.store, customStore]);

  const [brandFilter, setBrandFilter] = useState(null); // null = all brands

  const dates = useMemo(() => dateRangeArray(skuFrom, skuTo), [skuFrom, skuTo]);
  const rangeLen = dates.length;
  const prevWeekDates = useMemo(() => dateRangeArray(shiftDaysDate(skuFrom, -rangeLen), shiftDaysDate(skuTo, -rangeLen)), [skuFrom, skuTo, rangeLen]);
  const lyDates = useMemo(() => dates.map((d) => shiftYearDate(d, -1)), [dates]);

  const rowsAllBrands = useMemo(() => {
    const dateSet = new Set(dates);
    const map = new Map();
    for (const r of ctx.data.sku) {
      if (skuStore !== "ALL" && r.store !== skuStore) continue;
      if (!dateSet.has(r.date)) continue;
      if (!map.has(r.sku)) map.set(r.sku, { sku: r.sku, desc: r.desc, brand: r.brand || "OTHER", price: r.price, qty: 0, netSales: 0 });
      const o = map.get(r.sku); o.qty += r.qty; o.netSales += r.netSales;
    }
    return Array.from(map.values()).sort((a, b) => b.qty - a.qty);
  }, [ctx.data.sku, skuStore, dates]);

  const brandOptions = useMemo(() => {
    const m = new Map();
    for (const r of rowsAllBrands) m.set(r.brand, (m.get(r.brand) || 0) + r.qty);
    return Array.from(m.entries()).sort((a, b) => b[1] - a[1]).map(([b]) => b);
  }, [rowsAllBrands]);

  const rows = useMemo(() => {
    const filtered = brandFilter ? rowsAllBrands.filter((r) => brandFilter.has(r.brand)) : rowsAllBrands;
    return filtered.slice(0, 20);
  }, [rowsAllBrands, brandFilter]);

  const prevQty = useMemo(() => {
    const dateSet = new Set(prevWeekDates); const m = new Map();
    for (const r of ctx.data.sku) { if (skuStore !== "ALL" && r.store !== skuStore) continue; if (!dateSet.has(r.date)) continue; m.set(r.sku, (m.get(r.sku) || 0) + r.qty); }
    return m;
  }, [ctx.data.sku, skuStore, prevWeekDates]);

  const lyQty = useMemo(() => {
    const dateSet = new Set(lyDates); const m = new Map();
    for (const r of ctx.lyData.sku) { if (skuStore !== "ALL" && r.store !== skuStore) continue; if (!dateSet.has(r.date)) continue; m.set(r.sku, (m.get(r.sku) || 0) + r.qty); }
    return m;
  }, [ctx.lyData.sku, skuStore, lyDates]);

  const totalQty = rows.reduce((s, r) => s + r.qty, 0);
  const filterActive = customStore || customRange || brandFilter !== null;

  return (
    <div>
      <FilterDropdown active={filterActive}>
        <label><input type="checkbox" checked={customStore} onChange={(e) => setCustomStore(e.target.checked)} /> เลือกสาขาของตัวเอง</label>
        {customStore && (
          <select value={skuStore} onChange={(e) => setSkuStore(e.target.value)} style={{ width: "auto" }}>
            <option value="ALL">ทุกสาขา</option>
            {ctx.stores.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        )}
        <label><input type="checkbox" checked={customRange} onChange={(e) => setCustomRange(e.target.checked)} /> ช่วงวันที่ของตัวเอง</label>
        {customRange && (<>
          <input type="date" value={skuFrom} onChange={(e) => setSkuFrom(e.target.value)} />
          <input type="date" value={skuTo} min={skuFrom} onChange={(e) => setSkuTo(e.target.value)} />
        </>)}
        <div className="chip-row">
          {brandOptions.slice(0, 16).map((b) => {
            const active = !brandFilter || brandFilter.has(b);
            return (
              <button key={b} className={`chip${active ? " chip-active" : ""}`}
                onClick={() => setBrandFilter((prev) => {
                  const s = prev ? new Set(prev) : new Set(brandOptions);
                  if (s.has(b)) s.delete(b); else s.add(b);
                  return s;
                })}>{b}</button>
            );
          })}
          {brandFilter && <button className="chip chip-reset" onClick={() => setBrandFilter(null)}>แสดงทุกแบรนด์</button>}
          {brandOptions.length > 0 && (!brandFilter || brandFilter.size > 0) && <button className="chip chip-clear" onClick={() => setBrandFilter(new Set())}>ล้างทั้งหมด</button>}
        </div>
      </FilterDropdown>
      <table className="data-table sku-table">
        <thead><tr><th>#</th><th>SKU / รายการ</th><th>แบรนด์</th><th className="num">ราคา</th><th className="num">จำนวน (ชิ้น)</th><th className="num">% ยอดขาย</th><th className="num">WoW</th><th className="num">YoY</th></tr></thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={r.sku}>
              <td>{i + 1}</td>
              <td><div className="sku-desc">{r.desc || r.sku}</div><div className="sku-code">{r.sku}</div></td>
              <td>{r.brand}</td>
              <td className="num">{thb(r.price)}</td>

              <td className="num">{num(r.qty)}</td>
              <td className="num">{totalQty ? ((r.qty / totalQty) * 100).toFixed(1) : "0.0"}%</td>
              <td className="num"><GrowthBadge value={prevQty.has(r.sku) ? growth(r.qty, prevQty.get(r.sku)) : null} /></td>
              <td className="num"><GrowthBadge value={lyQty.has(r.sku) ? growth(r.qty, lyQty.get(r.sku)) : null} /></td>
            </tr>
          ))}
          {rows.length === 0 && <tr><td colSpan={8} className="empty-hint">ไม่มีข้อมูลในช่วงที่เลือก</td></tr>}
        </tbody>
      </table>
      <div className="widget-note">* จัดอันดับจากยอดชิ้นขายสูงสุด (Top 20) · WoW เทียบสัปดาห์ก่อนหน้าความยาวเท่ากัน · ข้อมูลตัวอย่างครอบคลุมเฉพาะ SKU ขายดี Top 200 ของไฟล์ตั้งต้น ไฟล์ที่อัปโหลดใหม่จะครอบคลุมทุก SKU</div>
    </div>
  );
}

/* ==================================================================== */
/* Discount reason widget                                                */
/* ==================================================================== */
function DiscountReasonWidget({ ctx }) {
  const [customStore, setCustomStore] = useState(false);
  const [drStore, setDrStore] = useState(ctx.store);
  useEffect(() => { if (!customStore) setDrStore(ctx.store); }, [ctx.store, customStore]);

  const [customRange, setCustomRange] = useState(false);
  const [drFrom, setDrFrom] = useState(ctx.from);
  const [drTo, setDrTo] = useState(ctx.to);
  useEffect(() => { if (!customRange) { setDrFrom(ctx.from); setDrTo(ctx.to); } }, [ctx.from, ctx.to, customRange]);

  const [reasonFilter, setReasonFilter] = useState(null); // null = all reasons

  const dates = useMemo(() => dateRangeArray(drFrom, drTo), [drFrom, drTo]);
  const totalBills = useMemo(() => sumKpi(ctx.data.kpi, drStore, dates).receipts, [ctx.data.kpi, drStore, dates]);

  const allRows = useMemo(() => {
    const grouped = groupSum(ctx.data.discReason, drStore, dates, "reason", ["bills", "discountValue"]);
    return grouped.sort((a, b) => b.bills - a.bills);
  }, [ctx.data.discReason, drStore, dates]);

  const rows = reasonFilter ? allRows.filter((r) => reasonFilter.has(r.reason)) : allRows;
  const filterActive = customStore || customRange || reasonFilter !== null;

  return (
    <div>
      <FilterDropdown active={filterActive}>
        <label><input type="checkbox" checked={customStore} onChange={(e) => setCustomStore(e.target.checked)} /> เลือกสาขาของตัวเอง</label>
        {customStore && (
          <select value={drStore} onChange={(e) => setDrStore(e.target.value)} style={{ width: "auto" }}>
            <option value="ALL">ทุกสาขา</option>
            {ctx.stores.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        )}
        <label><input type="checkbox" checked={customRange} onChange={(e) => setCustomRange(e.target.checked)} /> ช่วงวันที่ของตัวเอง</label>
        {customRange && (<>
          <input type="date" value={drFrom} onChange={(e) => setDrFrom(e.target.value)} />
          <input type="date" value={drTo} min={drFrom} onChange={(e) => setDrTo(e.target.value)} />
        </>)}
        <div className="chip-row">
          {allRows.map((r) => {
            const active = !reasonFilter || reasonFilter.has(r.reason);
            return (
              <button key={r.reason} className={`chip${active ? " chip-active" : ""}`}
                onClick={() => setReasonFilter((prev) => {
                  const s = prev ? new Set(prev) : new Set(allRows.map((x) => x.reason));
                  if (s.has(r.reason)) s.delete(r.reason); else s.add(r.reason);
                  return s;
                })}>{r.reason}</button>
            );
          })}
          {reasonFilter && <button className="chip chip-reset" onClick={() => setReasonFilter(null)}>แสดงทุกเหตุผล</button>}
          {allRows.length > 0 && (!reasonFilter || reasonFilter.size > 0) && <button className="chip chip-clear" onClick={() => setReasonFilter(new Set())}>ล้างทั้งหมด</button>}
        </div>
      </FilterDropdown>
      <table className="data-table">
        <thead><tr><th>เหตุผลส่วนลด</th><th className="num">จำนวนบิล</th><th className="num">% ของบิลทั้งหมด</th><th className="num">มูลค่าส่วนลด</th></tr></thead>
        <tbody>
          {rows.map((r) => (<tr key={r.reason}><td>{r.reason}</td><td className="num">{num(r.bills)}</td><td className="num">{totalBills ? ((r.bills / totalBills) * 100).toFixed(1) : "0.0"}%</td><td className="num">{thb(r.discountValue)}</td></tr>))}
          {rows.length === 0 && <tr><td colSpan={4} className="empty-hint">ไม่มีบิลที่ใช้ส่วนลดในช่วงนี้</td></tr>}
        </tbody>
      </table>
    </div>
  );
}

/* ==================================================================== */
/* Sales person leaderboard widget                                       */
/* ==================================================================== */
function SalesPersonWidget({ ctx }) {
  const [customStore, setCustomStore] = useState(false);
  const [spStore, setSpStore] = useState(ctx.store);
  useEffect(() => { if (!customStore) setSpStore(ctx.store); }, [ctx.store, customStore]);

  const [customRange, setCustomRange] = useState(false);
  const [spFrom, setSpFrom] = useState(ctx.from);
  const [spTo, setSpTo] = useState(ctx.to);
  useEffect(() => { if (!customRange) { setSpFrom(ctx.from); setSpTo(ctx.to); } }, [ctx.from, ctx.to, customRange]);

  const dates = useMemo(() => dateRangeArray(spFrom, spTo), [spFrom, spTo]);

  const rows = useMemo(() => {
    const grouped = groupSum(ctx.data.salesPerson, spStore, dates, "person", ["netSales", "qty"]);
    return grouped.sort((a, b) => b.netSales - a.netSales).slice(0, 15);
  }, [ctx.data.salesPerson, spStore, dates]);

  const filterActive = customStore || customRange;

  return (
    <div>
      <FilterDropdown active={filterActive}>
        <label><input type="checkbox" checked={customStore} onChange={(e) => setCustomStore(e.target.checked)} /> เลือกสาขาของตัวเอง</label>
        {customStore && (
          <select value={spStore} onChange={(e) => setSpStore(e.target.value)} style={{ width: "auto" }}>
            <option value="ALL">ทุกสาขา</option>
            {ctx.stores.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        )}
        <label><input type="checkbox" checked={customRange} onChange={(e) => setCustomRange(e.target.checked)} /> ช่วงวันที่ของตัวเอง</label>
        {customRange && (<>
          <input type="date" value={spFrom} onChange={(e) => setSpFrom(e.target.value)} />
          <input type="date" value={spTo} min={spFrom} onChange={(e) => setSpTo(e.target.value)} />
        </>)}
      </FilterDropdown>
      <table className="data-table">
        <thead><tr><th>#</th><th>รหัสพนักงาน</th><th className="num">ยอดขาย</th><th className="num">จำนวนชิ้น</th></tr></thead>
        <tbody>{rows.map((r, i) => (<tr key={r.person}><td>{i + 1}</td><td>{r.person}</td><td className="num">{thb(r.netSales)}</td><td className="num">{num(r.qty)}</td></tr>))}
          {rows.length === 0 && <tr><td colSpan={4} className="empty-hint">ไม่มีข้อมูล</td></tr>}
        </tbody>
      </table>
    </div>
  );
}

/* ==================================================================== */
/* Promotion & Tender widget                                             */
/* ==================================================================== */
function PromotionTenderWidget({ ctx }) {
  const [customStore, setCustomStore] = useState(false);
  const [ptStore, setPtStore] = useState(ctx.store);
  useEffect(() => { if (!customStore) setPtStore(ctx.store); }, [ctx.store, customStore]);

  const [customRange, setCustomRange] = useState(false);
  const [ptFrom, setPtFrom] = useState(ctx.from);
  const [ptTo, setPtTo] = useState(ctx.to);
  useEffect(() => { if (!customRange) { setPtFrom(ctx.from); setPtTo(ctx.to); } }, [ctx.from, ctx.to, customRange]);

  const dates = useMemo(() => dateRangeArray(ptFrom, ptTo), [ptFrom, ptTo]);

  const promo = sumKpi(ctx.data.promo.map((r) => ({ ...r, netSales: r.promoBills, grossSales: 0, discount: 0, qty: 0, tax: 0, receipts: 0 })), ptStore, dates);
  const promoBills = promo.netSales;
  const totalBills = sumKpi(ctx.data.kpi, ptStore, dates).receipts;

  const [voucherFilter, setVoucherFilter] = useState(null); // null = all voucher types (V-AH)

  const tenderRows = useMemo(() => {
    const dateSet = new Set(dates);
    let totalTender = 0; const payment = {}; const voucher = {};
    for (const r of ctx.tenderCurrent) {
      if (ptStore !== "ALL" && r.store !== ptStore) continue;
      if (!dateSet.has(r.date)) continue;
      totalTender += r.totalTender;
      for (const [k, v] of Object.entries(r.payment)) payment[k] = (payment[k] || 0) + v;
      for (const [k, v] of Object.entries(r.voucher)) voucher[k] = (voucher[k] || 0) + v;
    }
    return { totalTender, payment, voucher };
  }, [ctx.tenderCurrent, ptStore, dates]);

  const paymentList = Object.entries(tenderRows.payment).filter(([, v]) => v > 0).sort((a, b) => b[1] - a[1]);

  const allVoucherEntries = useMemo(() =>
    TENDER_VOUCHER_COLS.map((c) => [c, tenderRows.voucher[c] || 0]).sort((a, b) => b[1] - a[1])
  , [tenderRows.voucher]);
  const voucherTypesWithData = allVoucherEntries.filter(([, v]) => v > 0).map(([k]) => k);
  const voucherList = voucherFilter
    ? allVoucherEntries.filter(([k]) => voucherFilter.has(k))
    : allVoucherEntries.filter(([, v]) => v > 0);

  return (
    <div>
      <FilterDropdown active={customStore || customRange}>
        <label><input type="checkbox" checked={customStore} onChange={(e) => setCustomStore(e.target.checked)} /> เลือกสาขาของตัวเอง</label>
        {customStore && (
          <select value={ptStore} onChange={(e) => setPtStore(e.target.value)} style={{ width: "auto" }}>
            <option value="ALL">ทุกสาขา</option>
            {ctx.stores.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        )}
        <label><input type="checkbox" checked={customRange} onChange={(e) => setCustomRange(e.target.checked)} /> ช่วงวันที่ของตัวเอง</label>
        {customRange && (<>
          <input type="date" value={ptFrom} onChange={(e) => setPtFrom(e.target.value)} />
          <input type="date" value={ptTo} min={ptFrom} onChange={(e) => setPtTo(e.target.value)} />
        </>)}
      </FilterDropdown>
      <div className="promo-summary">
        <MiniStat label="บิลที่ใช้โปรโมชั่น" value={num(promoBills)} sub={`จาก ${num(totalBills)} บิลทั้งหมด`} />
        <MiniStat label="% บิลที่ใช้โปรโมชั่น" value={totalBills ? `${((promoBills / totalBills) * 100).toFixed(1)}%` : "0.0%"} />
        <MiniStat label="ยอดรวม Tender" value={tenderRows.totalTender ? thb(tenderRows.totalTender) : "ยังไม่มีข้อมูล"} sub={tenderRows.totalTender ? null : "อัปโหลดไฟล์ Tender"} />
      </div>
      {paymentList.length > 0 && (
        <>
          <div className="panel-title" style={{ marginTop: ".8rem" }}>ช่องทางชำระเงิน</div>
          <table className="data-table">
            <thead><tr><th>ช่องทาง</th><th className="num">ยอดเงิน</th><th className="num">% ของ Tender</th></tr></thead>
            <tbody>{paymentList.map(([k, v]) => (<tr key={k}><td>{k}</td><td className="num">{thb(v)}</td><td className="num">{tenderRows.totalTender ? ((v / tenderRows.totalTender) * 100).toFixed(1) : "0.0"}%</td></tr>))}</tbody>
          </table>
        </>
      )}
      <div>
        <div className="panel-title" style={{ marginTop: ".8rem" }}>คูปอง / Voucher (คอลัมน์ V-AH)</div>
        <FilterDropdown active={voucherFilter !== null} label="ตัวกรองประเภทคูปอง">
          <div className="chip-row">
            {TENDER_VOUCHER_COLS.map((c) => {
              const active = !voucherFilter || voucherFilter.has(c);
              const hasData = voucherTypesWithData.includes(c);
              return (
                <button key={c} className={`chip${active ? " chip-active" : ""}${hasData ? "" : " chip-empty"}`}
                  onClick={() => setVoucherFilter((prev) => {
                    const s = prev ? new Set(prev) : new Set(TENDER_VOUCHER_COLS);
                    if (s.has(c)) s.delete(c); else s.add(c);
                    return s;
                  })}>{c}</button>
              );
            })}
            {voucherFilter && <button className="chip chip-reset" onClick={() => setVoucherFilter(null)}>แสดงทุกประเภท</button>}
            <button className="chip chip-clear" onClick={() => setVoucherFilter(new Set())}>ล้างทั้งหมด</button>
          </div>
        </FilterDropdown>
        {tenderRows.totalTender > 0 ? (
          <table className="data-table">
            <thead><tr><th>ประเภท</th><th className="num">มูลค่าที่แลก</th></tr></thead>
            <tbody>
              {voucherList.map(([k, v]) => (<tr key={k}><td>{k}</td><td className="num">{thb(v)}</td></tr>))}
              {voucherList.length === 0 && <tr><td colSpan={2} className="empty-hint">ไม่มีข้อมูลตามตัวกรองที่เลือก</td></tr>}
            </tbody>
          </table>
        ) : (
          <div className="empty-hint">ยังไม่มีข้อมูล — เปิดตัวกรองด้านบนพร้อมใช้งานทันทีที่อัปโหลดไฟล์ Tender</div>
        )}
      </div>
      {paymentList.length === 0 && tenderRows.totalTender === 0 && (
        <div className="empty-hint" style={{ marginTop: ".6rem" }}>อัปโหลดไฟล์ Tender (แท็บ Tender ในชีตต้นทาง) เพื่อดูช่องทางชำระเงินและคูปอง</div>
      )}
    </div>
  );
}

