function PhotoWidget({ ctx, widgetId }) {
  const prefix = widgetId || "photos";
  const key = `${prefix}:${ctx.store}:${ctx.from}:${ctx.to}`;
  const [photos, setPhotos] = useState([]);
  const inputRef = useRef(null);

  const load = useCallback(async () => {
    try { const v = await window.storage.get(key, true); setPhotos(v?.value ? JSON.parse(v.value) : []); } catch (e) { setPhotos([]); }
  }, [key]);
  useEffect(() => { load(); }, [load]);

  const persist = async (list) => { try { await window.storage.set(key, JSON.stringify(list), true); } catch (e) { ctx.showToast("error", "บันทึกรูปไม่สำเร็จ (อาจมีขนาดใหญ่เกินไป)"); } };

  const handleFiles = (files) => {
    const list = Array.from(files || []).slice(0, 6 - photos.length);
    list.forEach((file) => {
      const img = new Image();
      const reader = new FileReader();
      reader.onload = (ev) => {
        img.onload = () => {
          const canvas = document.createElement("canvas");
          const scale = Math.min(1, 480 / img.width);
          canvas.width = img.width * scale; canvas.height = img.height * scale;
          canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
          const dataUrl = canvas.toDataURL("image/jpeg", 0.7);
          setPhotos((prev) => { const next = [...prev, dataUrl]; persist(next); return next; });
        };
        img.src = ev.target.result;
      };
      reader.readAsDataURL(file);
    });
  };

  const removePhoto = (idx) => setPhotos((prev) => { const next = prev.filter((_, i) => i !== idx); persist(next); return next; });

  return (
    <div>
      <div className="photo-grid">
        {photos.map((p, i) => (
          <div className="photo-thumb" key={i}>
            <img src={p} alt={`photo-${i}`} />
            <button className="photo-remove no-print" onClick={() => removePhoto(i)}><X size={12} /></button>
          </div>
        ))}
        {photos.length < 6 && (
          <button className="photo-add no-print" onClick={() => inputRef.current?.click()}><Camera size={20} /><span>เพิ่มรูป</span></button>
        )}
      </div>
      <input ref={inputRef} type="file" accept="image/*" multiple hidden onChange={(e) => { handleFiles(e.target.files); e.target.value = ""; }} />
      <div className="widget-note">* รองรับสูงสุด 6 รูปต่อสาขา/ช่วงเวลา (ย่อขนาดอัตโนมัติเพื่อประหยัดพื้นที่จัดเก็บ)</div>
    </div>
  );
}

/* ==================================================================== */
/* Perfect Bill widget (FTW / APP / ACC)                                 */
/* ==================================================================== */
function PerfectBillWidget({ ctx, category, widgetId }) {
  const [customRange, setCustomRange] = useState(false);
  const [pbFrom, setPbFrom] = useState(ctx.from);
  const [pbTo, setPbTo] = useState(ctx.to);
  useEffect(() => { if (!customRange) { setPbFrom(ctx.from); setPbTo(ctx.to); } }, [ctx.from, ctx.to, customRange]);

  const keyPrefix = widgetId || `perfectbill:${category}`;
  const key = `${keyPrefix}:${ctx.store}:${pbFrom}:${pbTo}`;
  const [conPct, setConPct] = useState("");
  const [perfectAtv, setPerfectAtv] = useState("");
  const [manpower, setManpower] = useState("");
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    (async () => {
      setSaved(false);
      try {
        const v = await window.storage.get(key, true);
        if (v?.value) {
          const p = JSON.parse(v.value);
          setConPct(p.conPct ?? ""); setPerfectAtv(p.perfectAtv ?? ""); setManpower(p.manpower ?? "");
          setSaved(true);
        } else { setConPct(""); setPerfectAtv(""); setManpower(""); }
      } catch (e) { setConPct(""); setPerfectAtv(""); setManpower(""); }
    })();
  }, [key]);

  const dailyTarget = useMemo(() => {
    const mo = monthKey(pbTo);
    const rows = ctx.targets.filter((t) => (ctx.store === "ALL" || t.store === ctx.store) && (t.month === mo || t.month === "ALL"));
    if (rows.length === 0) return null;
    const monthlyTarget = rows.reduce((s, r) => s + r.target, 0);
    const [y, m] = pbTo.split("-").map(Number);
    const daysInMonth = new Date(Date.UTC(y, m, 0)).getUTCDate();
    return monthlyTarget / daysInMonth;
  }, [ctx.targets, ctx.store, pbTo]);

  const conNum = Number(conPct) || 0;
  const targetCat = dailyTarget !== null ? dailyTarget * (conNum / 100) : null;
  const atvNum = Number(perfectAtv) || 0;
  const mpNum = Number(manpower) || 0;
  const perfectBillFocus = mpNum ? atvNum / mpNum : null;

  const save = async () => {
    try {
      await window.storage.set(key, JSON.stringify({ conPct, perfectAtv, manpower, savedAt: new Date().toISOString() }), true);
      setSaved(true); ctx.showToast("success", "บันทึกแล้ว");
    } catch (e) { ctx.showToast("error", "บันทึกไม่สำเร็จ"); }
  };

  return (
    <div>
      <FilterDropdown active={customRange}>
        <label><input type="checkbox" checked={customRange} onChange={(e) => setCustomRange(e.target.checked)} /> ช่วงวันที่ของตัวเอง</label>
        {customRange && (<>
          <input type="date" value={pbFrom} onChange={(e) => setPbFrom(e.target.value)} />
          <input type="date" value={pbTo} min={pbFrom} onChange={(e) => setPbTo(e.target.value)} />
        </>)}
      </FilterDropdown>
      <div className="pb-row">
      <span className="pb-item">
        <label className="pb-label">Con%</label>
        <input type="number" step="0.1" placeholder="35" value={conPct} onChange={(e) => { setConPct(e.target.value); setSaved(false); }} />
      </span>
      <span className="pb-item pb-computed">
        <label className="pb-label">Target CAT</label>
        <b className="pb-value">{dailyTarget !== null ? thb(targetCat) : "รอ Target"}</b>
      </span>
      <span className="pb-item">
        <label className="pb-label">Perfect ATV</label>
        <input type="number" placeholder="บาท" value={perfectAtv} onChange={(e) => { setPerfectAtv(e.target.value); setSaved(false); }} />
      </span>
      <span className="pb-item">
        <label className="pb-label">ManPower</label>
        <input type="number" placeholder="คน" value={manpower} onChange={(e) => { setManpower(e.target.value); setSaved(false); }} />
      </span>
      <span className="pb-item pb-computed">
        <label className="pb-label">Perfect Bill Focus</label>
        <b className="pb-value">{perfectBillFocus !== null ? num(perfectBillFocus) : "—"}</b>
      </span>
      <button className="btn btn-primary no-print pb-save" onClick={save} disabled={saved}>
        <Save size={13} /> {saved ? "บันทึกแล้ว" : "บันทึก"}
      </button>
    </div>
    </div>
  );
}

/* ==================================================================== */
/* Store Visit widget                                                    */
/* ==================================================================== */
function StoreVisitWidget({ ctx, widgetId }) {
  const [customRange, setCustomRange] = useState(false);
  const [svFrom, setSvFrom] = useState(ctx.from);
  const [svTo, setSvTo] = useState(ctx.to);
  useEffect(() => { if (!customRange) { setSvFrom(ctx.from); setSvTo(ctx.to); } }, [ctx.from, ctx.to, customRange]);

  const prefix = widgetId || "storevisit";
  const key = `${prefix}:${ctx.store}:${svFrom}:${svTo}`;

  const [challenge, setChallenge] = useState("");
  const [details, setDetails] = useState("");
  const [actionPlan, setActionPlan] = useState("");
  const [items, setItems] = useState([]);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    try {
      const list = await window.storage.list(`${prefix}:`, true);
      const keys = list?.keys || [];
      const out = [];
      for (const kk of keys) {
        try { const v = await window.storage.get(kk, true); if (v?.value) out.push({ key: kk, ...JSON.parse(v.value) }); } catch (e) {}
      }
      out.sort((a, b) => (b.savedAt || "").localeCompare(a.savedAt || ""));
      setItems(out);
    } catch (e) {}
  }, [prefix]);
  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    (async () => {
      try {
        const v = await window.storage.get(key, true);
        if (v?.value) { const p = JSON.parse(v.value); setChallenge(p.challenge || ""); setDetails(p.details || ""); setActionPlan(p.actionPlan || ""); }
        else { setChallenge(""); setDetails(""); setActionPlan(""); }
      } catch (e) { setChallenge(""); setDetails(""); setActionPlan(""); }
    })();
  }, [key]);

  const save = async () => {
    setSaving(true);
    try {
      await window.storage.set(key, JSON.stringify({ store: ctx.store, from: svFrom, to: svTo, challenge, details, actionPlan, savedAt: new Date().toISOString() }), true);
      ctx.showToast("success", "บันทึก Store Visit แล้ว"); load();
    } catch (e) { ctx.showToast("error", "บันทึกไม่สำเร็จ"); }
    setSaving(false);
  };

  return (
    <div>
      <FilterDropdown active={customRange}>
        <label><input type="checkbox" checked={customRange} onChange={(e) => setCustomRange(e.target.checked)} /> ช่วงวันที่ของตัวเอง</label>
        {customRange && (<>
          <input type="date" value={svFrom} onChange={(e) => setSvFrom(e.target.value)} />
          <input type="date" value={svTo} min={svFrom} onChange={(e) => setSvTo(e.target.value)} />
        </>)}
      </FilterDropdown>
      <label className="field-label">Challenge</label>
      <textarea value={challenge} onChange={(e) => setChallenge(e.target.value)} placeholder="ความท้าทายที่พบระหว่างตรวจเยี่ยมร้าน..." />
      <label className="field-label">Details</label>
      <textarea value={details} onChange={(e) => setDetails(e.target.value)} placeholder="รายละเอียดเพิ่มเติม..." />
      <label className="field-label">Action Plan</label>
      <textarea value={actionPlan} onChange={(e) => setActionPlan(e.target.value)} placeholder="แผนดำเนินการ..." />
      <div style={{ display: "flex", justifyContent: "flex-end", marginTop: ".5rem" }}>
        <button className="btn btn-primary no-print" onClick={save} disabled={saving}><Save size={14} /> บันทึก</button>
      </div>
      {items.length > 0 && (
        <div style={{ marginTop: ".8rem", paddingTop: ".7rem", borderTop: "1px solid var(--line)" }}>
          <div className="panel-title">ประวัติ Store Visit</div>
          {items.slice(0, 5).map((n) => (
            <div className="note-item" key={n.key}>
              <div className="note-meta"><b>{n.store === "ALL" ? "ทุกสาขา" : n.store}</b><span>{n.from} – {n.to}</span><span>· {new Date(n.savedAt).toLocaleString("th-TH")}</span></div>
              <div className="note-text"><b>Challenge:</b> {n.challenge || "-"}</div>
              <div className="note-text"><b>Details:</b> {n.details || "-"}</div>
              <div className="note-text"><b>Action Plan:</b> {n.actionPlan || "-"}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

