function VatRefundWidget({ ctx }) {
  const iframeRef = useRef(null);
  const [ready, setReady] = useState(false);

  const postData = useCallback(() => {
    const win = iframeRef.current && iframeRef.current.contentWindow;
    if (!win) return;
    if (!ctx.vatRefundRows || ctx.vatRefundRows.length === 0) return;
    win.postMessage({ type: "vat-rows", rows: ctx.vatRefundRows }, "*");
  }, [ctx.vatRefundRows]);

  useEffect(() => { if (ready) postData(); }, [ready, postData]);

  return (
    <div className="vat-iframe-wrap">
      <iframe
        ref={iframeRef}
        title="VAT Refund Tracker"
        srcDoc={VAT_REFUND_HTML}
        onLoad={() => setReady(true)}
        className="vat-iframe"
      />
      <div className="widget-note">* อัปโหลดไฟล์ที่หน้า YOUR SOURCE (Mapping Tool) ช่อง "VAT Refund / นักท่องเที่ยว" — ข้อมูลจะเข้ามาที่นี่อัตโนมัติ ไม่ต้องอัปโหลดซ้ำในนี้</div>
    </div>
  );
}

