/* ==================================================================== */
/* Tasks widget — admin creates tasks in Mapping Tool, staff see & tick  */
/* them off here; incomplete tasks also trigger the alert banner above.  */
/* ==================================================================== */
function isTaskRelevantFor(task, store, nickname) {
  const storeMatch = task.toStore === "ALL" || task.toStore === store;
  const personMatch = !task.assignedTo || task.assignedTo === "ALL" || task.assignedTo === nickname;
  return storeMatch && personMatch;
}

function TasksWidget({ ctx }) {
  const relevant = useMemo(() => {
    const list = ctx.tasks.filter((t) => ctx.store === "ALL" ? true : isTaskRelevantFor(t, ctx.store, ctx.session?.nickname));
    return list.sort((a, b) => {
      if (a.completed !== b.completed) return a.completed ? 1 : -1;
      return (a.deadline || "").localeCompare(b.deadline || "");
    });
  }, [ctx.tasks, ctx.store, ctx.session]);

  const toggleComplete = (task) => {
    ctx.saveTask({ ...task, completed: !task.completed, completedAt: !task.completed ? new Date().toISOString() : null });
  };

  const today = new Date().toISOString().slice(0, 10);

  return (
    <div>
      {relevant.length === 0 ? (
        <div className="empty-hint">ไม่มีงานที่มอบหมายให้{ctx.store === "ALL" ? "สาขาใดเลย" : "สาขานี้"}ในตอนนี้</div>
      ) : (
        <div className="task-list">
          {relevant.map((t) => {
            const overdue = !t.completed && t.deadline && t.deadline < today;
            return <TaskCard key={t.id} task={t} overdue={overdue} onToggle={() => toggleComplete(t)} onSave={ctx.saveTask} showToast={ctx.showToast} onAddWidget={ctx.addInstance} />;
          })}
        </div>
      )}
    </div>
  );
}

function TaskCard({ task: t, overdue, onToggle, onSave, showToast, onAddWidget }) {
  const fileRef = useRef(null);
  const staffAttachments = t.staffAttachments || [];

  const handleFiles = (files) => {
    const list = Array.from(files || []).slice(0, 4 - staffAttachments.length);
    list.forEach((file) => {
      if (file.size > 2 * 1024 * 1024) { showToast("error", `ไฟล์ "${file.name}" ใหญ่เกิน 2MB`); return; }
      const isImage = file.type.startsWith("image/");
      const reader = new FileReader();
      reader.onload = (ev) => {
        if (isImage) {
          const img = new Image();
          img.onload = () => {
            const canvas = document.createElement("canvas");
            const scale = Math.min(1, 480 / img.width);
            canvas.width = img.width * scale; canvas.height = img.height * scale;
            canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
            const dataUrl = canvas.toDataURL("image/jpeg", 0.75);
            onSave({ ...t, staffAttachments: [...(t.staffAttachments || []), { name: file.name, dataUrl, isImage: true }] });
          };
          img.src = ev.target.result;
        } else {
          onSave({ ...t, staffAttachments: [...(t.staffAttachments || []), { name: file.name, dataUrl: ev.target.result, isImage: false }] });
        }
      };
      reader.readAsDataURL(file);
    });
  };

  const removeAttachment = (idx) => {
    onSave({ ...t, staffAttachments: staffAttachments.filter((_, i) => i !== idx) });
  };

  const linkedDef = t.linkedWidget ? WIDGET_DEFS[t.linkedWidget] : null;

  return (
    <div className={`task-card${t.completed ? " task-done" : ""}${overdue ? " task-overdue" : ""}`}>
      <label className="task-tick">
        <input type="checkbox" checked={!!t.completed} onChange={onToggle} />
      </label>
      <div className="task-body">
        <div className="task-head-row">
          <div className="task-topic">{t.topics}</div>
          {overdue && <span className="badge badge-neg">เลยกำหนด</span>}
          {t.completed && <span className="badge badge-pos">เสร็จแล้ว</span>}
        </div>
        <div className="task-meta">
          <span>สาขา: {t.toStore === "ALL" ? "ทุกสาขา" : t.toStore}</span>
          <span>มอบหมายให้: {t.assignedTo && t.assignedTo !== "ALL" ? t.assignedTo : "ทุกคนในสาขา"}</span>
          <span>วันที่มอบหมาย: {t.assignDate || "-"}</span>
          <span>กำหนดส่ง: {t.deadline || "-"}</span>
        </div>
        {t.steps && t.steps.length > 0 && (
          <ol className="task-steps">
            {t.steps.map((s, i) => <li key={i}>{s}</li>)}
          </ol>
        )}
        {linkedDef && (
          <button className="btn btn-outline no-print task-widget-link" onClick={() => { onAddWidget(t.linkedWidget); showToast("success", `เพิ่ม Widget "${linkedDef.title}" แล้ว — เลื่อนลงไปดูด้านล่าง`); }}>
            {linkedDef.icon} เพิ่ม Widget "{linkedDef.title}" เพื่อทำงานนี้
          </button>
        )}
        {t.attachment && (
          <a className="task-attachment" href={t.attachment.dataUrl} download={t.attachment.name} target="_blank" rel="noreferrer">
            📎 {t.attachment.name} (จากแอดมิน)
          </a>
        )}

        <div className="task-staff-attach">
          <div className="task-staff-attach-label">แนบรูป/ไฟล์จากหน้าร้าน</div>
          <div className="photo-grid">
            {staffAttachments.map((a, i) => (
              <div className="photo-thumb" key={i}>
                {a.isImage ? <img src={a.dataUrl} alt="" /> : (
                  <a className="task-file-thumb" href={a.dataUrl} download={a.name} target="_blank" rel="noreferrer">📄<span>{a.name}</span></a>
                )}
                <button className="photo-remove no-print" onClick={() => removeAttachment(i)}><X size={12} /></button>
              </div>
            ))}
            {staffAttachments.length < 4 && (
              <button className="photo-add no-print" onClick={() => fileRef.current?.click()}><Camera size={18} /><span>เพิ่มไฟล์</span></button>
            )}
          </div>
          <input ref={fileRef} type="file" multiple hidden onChange={(e) => { handleFiles(e.target.files); e.target.value = ""; }} />
        </div>
      </div>
    </div>
  );
}

/* Fixed alert banner shown on YOUR BUILD, above the widget grid */
function TaskAlertBanner({ ctx }) {
  const today = new Date().toISOString().slice(0, 10);
  const pending = useMemo(() => {
    return ctx.tasks.filter((t) => !t.completed && (ctx.store === "ALL" ? true : isTaskRelevantFor(t, ctx.store, ctx.session?.nickname)));
  }, [ctx.tasks, ctx.store, ctx.session]);
  if (pending.length === 0) return null;
  const overdueCount = pending.filter((t) => t.deadline && t.deadline < today).length;
  return (
    <div className="task-alert no-print">
      <AlertCircle size={18} />
      <div className="task-alert-text">
        <b>มีงานค้าง {pending.length} รายการ</b>{overdueCount > 0 && <span> (เลยกำหนดแล้ว {overdueCount} รายการ)</span>} สำหรับ{ctx.store === "ALL" ? "ภาพรวมทุกสาขา" : ctx.store} — เปิด Widget "Tasks" เพื่อดูรายละเอียดและติ๊กเมื่อทำเสร็จ
      </div>
    </div>
  );
}

/* ==================================================================== */
/* Retailing Productivity — time & motion study for receiving/tagging/    */
/* displaying/stocking incoming shipments                                */
/* ==================================================================== */
const RP_PREFIX = "retailprod:";
const RP_SHIP_TYPES = ["IBT", "LF"];
const RP_STEP_DEFS = [
  {
    num: 1, title: "สแกนและรับสินค้า",
    subOptions: ["ยิงรับสินค้า"], allowCustomSub: true,
    qtyFields: [
      { key: "footwear", label: "FOOTWEAR" },
      { key: "app", label: "APP" },
      { key: "accBag", label: "ACC-BAG" },
      { key: "accCapSockCrep", label: "ACC-CAP, SOCK, CREP" },
    ],
  },
  {
    num: 2, title: "ทำป้ายราคาและนำขึ้นโชว์",
    subOptions: [
      "ติดสัญญาณตัวโชว์และจัดแสดงตัวอย่าง - รองเท้า",
      "ติดสัญญาณตัวโชว์และจัดแสดงตัวอย่าง - เสื้อผ้า",
      "ติดสัญญาณตัวโชว์และจัดแสดงตัวอย่าง - อุปกรณ์",
    ],
    allowCustomSub: false,
    qtyFields: [{ key: "tested", label: "จำนวนทดลอง" }],
  },
  {
    num: 3, title: "เก็บสินค้าในสต๊อกสินค้า",
    subOptions: [], allowCustomSub: false,
    qtyFields: [{ key: "amount", label: "จำนวน" }],
    productTypeOptions: ["FTW", "ACC"],
  },
  {
    num: 4, title: "แขวนเสื้อผ้าและนำขึ้นแขวนหลังบ้าน",
    subOptions: [], allowCustomSub: false,
    qtyFields: [],
  },
];

function rpBlankTest(code, store) {
  return {
    id: "",
    code,
    store: store || "",
    testDate: new Date().toISOString().slice(0, 10),
    doNumbers: [],
    boxCount: "",
    boxPhotos: [],
    shipmentType: RP_SHIP_TYPES[0],
    stepInstances: [],
    status: "draft",
    createdAt: new Date().toISOString(),
    submittedAt: null,
    submittedBy: null,
  };
}
function rpFmtTime(sec) {
  if (sec === null || sec === undefined) return "--:--";
  const m = Math.floor(sec / 60), s = sec % 60;
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}
function rpProductBreakdown(tests, storeFilter) {
  const rows = new Map();
  tests.forEach((t) => {
    if (storeFilter !== "ALL" && (t.store || "") !== storeFilter) return;
    (t.stepInstances || []).forEach((step) => {
      const def = RP_STEP_DEFS.find((d) => d.num === step.stepNum);
      if (!def) return;
      const timeSec = step.elapsedSec || 0;
      if (!timeSec) return;
      let entries = [];
      if (step.stepNum === 1) {
        entries = [
          { type: "FOOTWEAR", qty: Number(step.qty.footwear) || 0 },
          { type: "APP", qty: Number(step.qty.app) || 0 },
          { type: "ACC-BAG", qty: Number(step.qty.accBag) || 0 },
          { type: "ACC-CAP,SOCK,CREP", qty: Number(step.qty.accCapSockCrep) || 0 },
        ].filter((e) => e.qty > 0);
      } else if (step.stepNum === 2) {
        const label = step.subSteps.length ? step.subSteps.map((s) => (s.split(" - ")[1] || s).trim()).join(", ") : "ทั่วไป";
        const qty = Number(step.qty.tested) || 0;
        if (qty > 0) entries = [{ type: label, qty }];
      } else if (step.stepNum === 3) {
        const qty = Number(step.qty.amount) || 0;
        if (qty > 0 && step.productType) entries = [{ type: step.productType, qty }];
      }
      entries.forEach((e) => {
        const key = `${t.store || "-"}|${step.stepNum}|${e.type}`;
        if (!rows.has(key)) rows.set(key, { store: t.store || "-", stepNum: step.stepNum, stepTitle: def.title, productType: e.type, qty: 0, timeSec: 0 });
        const r = rows.get(key);
        r.qty += e.qty;
        r.timeSec += timeSec;
      });
    });
  });
  return Array.from(rows.values())
    .map((r) => ({ ...r, rate: r.qty > 0 ? r.timeSec / r.qty : null }))
    .sort((a, b) => a.stepNum - b.stepNum || a.store.localeCompare(b.store));
}

function rpGenCode(store) {
  const d = new Date();
  const ymd = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, "0")}${String(d.getDate()).padStart(2, "0")}`;
  const rand = Math.random().toString(36).slice(2, 6).toUpperCase();
  return `RP-${storeAbbr(store)}-${ymd}-${rand}`;
}

function RetailingProductivityWidget({ ctx }) {
  const [mode, setMode] = useState("menu"); // menu | resume | form | report
  const [test, setTest] = useState(null);
  const [allTests, setAllTests] = useState([]);
  const [resumeStoreFilter, setResumeStoreFilter] = useState("ALL");
  const [resumeDateFilter, setResumeDateFilter] = useState("");
  const [reportStoreFilter, setReportStoreFilter] = useState("ALL");
  const [doInput, setDoInput] = useState("");
  const [activeBoxIndex, setActiveBoxIndex] = useState(null);
  const [, forceTick] = useState(0);
  const fileRef = useRef(null);

  const load = useCallback(async () => {
    try {
      const list = await window.storage.list(RP_PREFIX, true);
      const keys = list?.keys || [];
      const out = [];
      for (const k of keys) { try { const v = await window.storage.get(k, true); if (v?.value) out.push(JSON.parse(v.value)); } catch (e) {} }
      out.sort((a, b) => (b.createdAt || "").localeCompare(a.createdAt || ""));
      setAllTests(out);
    } catch (e) {}
  }, []);
  useEffect(() => { load(); }, [load]);

  useEffect(() => {
    if (!test) return;
    const anyRunning = (test.stepInstances || []).some((s) => s.startedAt && !s.stoppedAt);
    if (!anyRunning) return;
    const id = setInterval(() => forceTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, [test]);

  const persistTest = async (payload, msg) => {
    try {
      await window.storage.set(RP_PREFIX + payload.id, JSON.stringify(payload), true);
      if (msg) ctx.showToast("success", msg);
      load();
    } catch (e) { ctx.showToast("error", "บันทึกไม่สำเร็จ"); }
  };

  const startNew = async () => {
    const defaultStore = ctx.store !== "ALL" ? ctx.store : (ctx.session?.store || ctx.stores[0] || "");
    const code = rpGenCode(defaultStore);
    const id = `rp_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    const blank = { ...rpBlankTest(code, defaultStore), id };
    setTest(blank);
    setMode("form");
    await persistTest(blank, `สร้างรหัสทดสอบ ${code} แล้ว — จำรหัสนี้ไว้ค้นหา/แก้ไขภายหลังได้`);
  };
  const resumeTest = (t) => { setTest(t); setMode("form"); };

  const updateTest = (patch) => setTest((prev) => ({ ...prev, ...patch }));
  const addStepInstance = (stepNum) => {
    const instanceId = `${stepNum}_${Date.now()}_${Math.random().toString(36).slice(2, 5)}`;
    const inst = { instanceId, stepNum, subSteps: [], customSub: "", productType: "", qty: {}, startedAt: null, stoppedAt: null, elapsedSec: null, savedAt: null };
    setTest((prev) => ({ ...prev, stepInstances: [...(prev.stepInstances || []), inst] }));
  };
  const updateStepInstance = (instanceId, patch) => setTest((prev) => ({ ...prev, stepInstances: prev.stepInstances.map((s) => (s.instanceId === instanceId ? { ...s, ...patch } : s)) }));
  const removeStepInstance = (instanceId) => setTest((prev) => ({ ...prev, stepInstances: prev.stepInstances.filter((s) => s.instanceId !== instanceId) }));
  const startTimer = (instanceId) => updateStepInstance(instanceId, { startedAt: Date.now(), stoppedAt: null, elapsedSec: null });
  const stopTimer = (instanceId) => {
    const step = test.stepInstances.find((s) => s.instanceId === instanceId);
    if (!step || !step.startedAt) return;
    updateStepInstance(instanceId, { stoppedAt: Date.now(), elapsedSec: Math.round((Date.now() - step.startedAt) / 1000) });
  };
  const liveElapsed = (step) => (step.startedAt && !step.stoppedAt ? Math.floor((Date.now() - step.startedAt) / 1000) : step.elapsedSec);

  const saveStepInstance = async (instanceId) => {
    const updated = { ...test, stepInstances: test.stepInstances.map((s) => (s.instanceId === instanceId ? { ...s, savedAt: new Date().toISOString() } : s)) };
    setTest(updated);
    await persistTest(updated, "บันทึกขั้นตอนนี้แล้ว");
  };
  const saveSetup = async () => { await persistTest(test, "บันทึกข้อมูลตั้งต้นแล้ว"); };

  const addDoNumber = () => {
    if (!doInput.trim()) return;
    setTest((prev) => ({ ...prev, doNumbers: [...(prev.doNumbers || []), doInput.trim()] }));
    setDoInput("");
  };
  const removeDoNumber = (i) => setTest((prev) => ({ ...prev, doNumbers: prev.doNumbers.filter((_, idx) => idx !== i) }));

  const setBoxCount = (val) => {
    const n = Math.max(0, parseInt(val, 10) || 0);
    setTest((prev) => {
      const photos = [...(prev.boxPhotos || [])];
      while (photos.length < n) photos.push(null);
      if (photos.length > n) photos.length = n;
      return { ...prev, boxCount: val, boxPhotos: photos };
    });
  };
  const openBoxPhotoPicker = (i) => { setActiveBoxIndex(i); fileRef.current?.click(); };
  const handleBoxPhoto = (file) => {
    if (!file || activeBoxIndex === null) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        const scale = Math.min(1, 480 / img.width);
        canvas.width = img.width * scale; canvas.height = img.height * scale;
        canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.7);
        setTest((prev) => {
          const photos = [...(prev.boxPhotos || [])];
          photos[activeBoxIndex] = dataUrl;
          return { ...prev, boxPhotos: photos };
        });
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  };
  const removeBoxPhoto = (i) => setTest((prev) => { const photos = [...(prev.boxPhotos || [])]; photos[i] = null; return { ...prev, boxPhotos: photos }; });

  const finalSubmit = async () => {
    const payload = { ...test, status: "submitted", submittedAt: new Date().toISOString(), submittedBy: ctx.session?.nickname || "-" };
    setTest(payload);
    await persistTest(payload, "ส่งข้อมูลแล้ว");
    setMode("menu");
  };

  const filteredDrafts = allTests.filter((t) => t.status === "draft" && (resumeStoreFilter === "ALL" || (t.store || "") === resumeStoreFilter) && (!resumeDateFilter || t.testDate === resumeDateFilter));

  return (
    <div>
      <div className="rp-menu no-print">
        <button className="btn btn-primary" onClick={startNew}><Plus size={14} /> เพิ่มการทดสอบ</button>
        <button className="btn btn-outline" onClick={() => setMode("resume")}><History size={14} /> เรียกการทดสอบเพื่อทำต่อ</button>
        <button className="btn btn-outline" onClick={() => setMode("report")}><FileSpreadsheet size={14} /> แสดงผล</button>
      </div>

      {mode === "resume" && (
        <div>
          <div className="rp-resume-filter">
            <div>
              <label className="field-label">เลือกสาขา</label>
              <select value={resumeStoreFilter} onChange={(e) => setResumeStoreFilter(e.target.value)}>
                <option value="ALL">ทุกสาขา</option>
                {ctx.stores.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div>
              <label className="field-label">เลือกวันที่ทดสอบ</label>
              <input type="date" value={resumeDateFilter} onChange={(e) => setResumeDateFilter(e.target.value)} />
            </div>
            {(resumeStoreFilter !== "ALL" || resumeDateFilter) && (
              <button className="btn btn-outline" onClick={() => { setResumeStoreFilter("ALL"); setResumeDateFilter(""); }}>ล้างตัวกรอง</button>
            )}
          </div>
          {filteredDrafts.length === 0 ? (
            <div className="empty-hint">ไม่พบแบบร่างที่ตรงกับตัวกรอง</div>
          ) : filteredDrafts.map((t) => (
            <div className="rp-test-row" key={t.id}>
              <div><b>{t.code}</b> · {t.store || "(ไม่ระบุสาขา)"} · DO {(t.doNumbers || []).length ? t.doNumbers.join(", ") : "(ไม่ระบุ)"} · {t.testDate} · {t.shipmentType} · {t.boxCount || 0} กล่อง · {(t.stepInstances || []).length} Step</div>
              <button className="btn btn-primary" onClick={() => resumeTest(t)}>ทำต่อ</button>
            </div>
          ))}
        </div>
      )}

      {mode === "report" && (
        <div>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", gap: ".6rem", flexWrap: "wrap", marginBottom: "1rem" }}>
            <div>
              <label className="field-label" style={{ margin: 0 }}>Filter สาขา</label>
              <select value={reportStoreFilter} onChange={(e) => setReportStoreFilter(e.target.value)} style={{ maxWidth: 260 }}>
                <option value="ALL">ทุกสาขา</option>
                {ctx.stores.map((s) => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <button className="btn btn-outline no-print" onClick={() => {
              const submitted = allTests.filter((t) => t.status === "submitted" && (reportStoreFilter === "ALL" || (t.store || "") === reportStoreFilter));
              const testRows = submitted.map((t) => ({
                "รหัสทดสอบ": t.code, "สาขา": t.store || "-", "DO": (t.doNumbers || []).join(", "), "วันที่": t.testDate,
                "รูปแบบ": t.shipmentType, "กล่อง": t.boxCount, "จำนวน Step": (t.stepInstances || []).length,
                "เวลารวม (วินาที)": (t.stepInstances || []).reduce((s, st) => s + (st.elapsedSec || 0), 0), "ผู้ส่ง": t.submittedBy,
              }));
              const breakdownRows = rpProductBreakdown(submitted, "ALL").map((r) => ({
                "สาขา": r.store, "Step": `Step ${r.stepNum} — ${r.stepTitle}`, "ประเภทสินค้าที่ทดสอบ": r.productType,
                "จำนวนชิ้น": r.qty, "เวลาที่ใช้ (วินาที)": r.timeSec.toFixed(0), "ผลลัพธ์ (วิ/ชิ้น)": r.rate !== null ? r.rate.toFixed(1) : "",
              }));
              exportToExcel(`RetailingProductivity_${new Date().toISOString().slice(0, 10)}.xlsx`, [{ name: "รายการทดสอบ", rows: testRows }, { name: "สรุปผลลัพธ์", rows: breakdownRows }]);
            }}><FileSpreadsheet size={14} /> Export เป็น Excel</button>
          </div>

          <div className="panel-title">สรุปรายการทดสอบ</div>
          <table className="data-table" style={{ marginBottom: "1.2rem" }}>
            <thead><tr><th>รหัสทดสอบ</th><th>สาขา</th><th>DO</th><th>วันที่</th><th>รูปแบบ</th><th className="num">กล่อง</th><th className="num">จำนวน Step</th><th className="num">เวลารวม</th><th>ผู้ส่ง</th></tr></thead>
            <tbody>
              {allTests.filter((t) => t.status === "submitted" && (reportStoreFilter === "ALL" || (t.store || "") === reportStoreFilter)).map((t) => {
                const total = (t.stepInstances || []).reduce((s, st) => s + (st.elapsedSec || 0), 0);
                return (
                  <tr key={t.id}>
                    <td>{t.code}</td><td>{t.store || "-"}</td><td>{(t.doNumbers || []).join(", ")}</td><td>{t.testDate}</td><td>{t.shipmentType}</td><td className="num">{t.boxCount}</td>
                    <td className="num">{(t.stepInstances || []).length}</td>
                    <td className="num">{rpFmtTime(total)}</td>
                    <td>{t.submittedBy}</td>
                  </tr>
                );
              })}
              {allTests.filter((t) => t.status === "submitted" && (reportStoreFilter === "ALL" || (t.store || "") === reportStoreFilter)).length === 0 && <tr><td colSpan={9} className="empty-hint">ยังไม่มีการทดสอบที่ส่งข้อมูลแล้ว</td></tr>}
            </tbody>
          </table>

          <div className="panel-title">สรุปผลลัพธ์ตามประเภทสินค้า / Step</div>
          <table className="data-table">
            <thead><tr><th>สาขา</th><th>Step</th><th>ประเภทสินค้าที่ทดสอบ</th><th className="num">จำนวนชิ้น</th><th className="num">เวลาที่ใช้ (วินาที)</th><th className="num">ผลลัพธ์</th></tr></thead>
            <tbody>
              {rpProductBreakdown(allTests.filter((t) => t.status === "submitted"), reportStoreFilter).map((r, i) => (
                <tr key={i}>
                  <td>{r.store}</td>
                  <td>Step {r.stepNum} — {r.stepTitle}</td>
                  <td>{r.productType}</td>
                  <td className="num">{num(r.qty)}</td>
                  <td className="num">{r.timeSec.toFixed(0)}</td>
                  <td className="num">{r.rate !== null ? `1 : ${r.rate.toFixed(1)} วิ/ชิ้น` : "-"}</td>
                </tr>
              ))}
              {rpProductBreakdown(allTests.filter((t) => t.status === "submitted"), reportStoreFilter).length === 0 && <tr><td colSpan={6} className="empty-hint">ยังไม่มีข้อมูลผลลัพธ์ตามประเภทสินค้า</td></tr>}
            </tbody>
          </table>
        </div>
      )}

      {mode === "form" && test && (
        <div>
          <div className="rp-code-banner">
            <div className="rp-code-label">รหัสทดสอบ (Test Code) — ใช้ค้นหา/แก้ไขภายหลัง</div>
            <div className="rp-code-value">{test.code}</div>
          </div>

          <div className="rp-setup">
            <label className="field-label">สาขา</label>
            <select value={test.store || ""} onChange={(e) => updateTest({ store: e.target.value })}>
              <option value="">(ไม่ระบุ)</option>
              {ctx.stores.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
            <label className="field-label">วันที่ทดสอบ</label>
            <input type="date" value={test.testDate} onChange={(e) => updateTest({ testDate: e.target.value })} />

            <label className="field-label">ระบุหมายเลข DO ที่จะทำการทดสอบ (เพิ่มได้หลายหมายเลข)</label>
            <div className="task-step-input-row">
              <input type="text" value={doInput} onChange={(e) => setDoInput(e.target.value)} placeholder="เช่น DO-20260901-001" onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); addDoNumber(); } }} />
              <button className="btn btn-outline" onClick={addDoNumber}><Plus size={13} /> เพิ่ม DO</button>
            </div>
            {(test.doNumbers || []).length > 0 && (
              <ol className="task-steps task-steps-form">
                {test.doNumbers.map((d, i) => (
                  <li key={i}>{d} <button className="task-step-remove" onClick={() => removeDoNumber(i)}><X size={11} /></button></li>
                ))}
              </ol>
            )}

            <label className="field-label">เลือกรูปแบบการส่งสินค้า</label>
            <select value={test.shipmentType} onChange={(e) => updateTest({ shipmentType: e.target.value })}>
              {RP_SHIP_TYPES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
            <label className="field-label">ระบุจำนวนกล่องที่ทดสอบ</label>
            <input type="number" value={test.boxCount} onChange={(e) => setBoxCount(e.target.value)} />

            {Number(test.boxCount) > 0 && (
              <>
                <label className="field-label">ถ่ายรูปฉลากแต่ละกล่อง</label>
                <div className="rp-box-photo-grid">
                  {(test.boxPhotos || []).map((photo, i) => (
                    <div className="rp-box-photo-slot" key={i}>
                      <div className="rp-box-photo-label">กล่องที่ {i + 1}</div>
                      {photo ? (
                        <div className="photo-thumb"><img src={photo} alt="" /><button className="photo-remove no-print" onClick={() => removeBoxPhoto(i)}><X size={12} /></button></div>
                      ) : (
                        <button className="photo-add no-print" onClick={() => openBoxPhotoPicker(i)}><Camera size={18} /><span>ถ่ายรูป</span></button>
                      )}
                    </div>
                  ))}
                </div>
              </>
            )}
            <input ref={fileRef} type="file" accept="image/*" hidden onChange={(e) => { handleBoxPhoto(e.target.files[0]); e.target.value = ""; }} />

            <div style={{ display: "flex", justifyContent: "flex-end", marginTop: ".6rem" }}>
              <button className="btn btn-outline no-print" onClick={saveSetup}><Save size={13} /> บันทึกข้อมูลตั้งต้น</button>
            </div>
          </div>

          <div className="rp-step-buttons no-print">
            {RP_STEP_DEFS.map((def) => (
              <button key={def.num} className="btn btn-outline" onClick={() => addStepInstance(def.num)}>+ Step {def.num}: {def.title}</button>
            ))}
          </div>

          {(test.stepInstances || []).length === 0 && <div className="empty-hint">ยังไม่มี Step ที่เพิ่ม — กดปุ่มด้านบนเพื่อเริ่มจับเวลา (เพิ่ม Step เดิมซ้ำได้ไม่จำกัดครั้ง)</div>}

          {(test.stepInstances || []).map((step, idx) => {
            const def = RP_STEP_DEFS.find((d) => d.num === step.stepNum);
            const running = !!(step.startedAt && !step.stoppedAt);
            const repIndex = test.stepInstances.slice(0, idx).filter((s) => s.stepNum === step.stepNum).length;
            return (
              <div className="rp-step" key={step.instanceId}>
                <div className="rp-step-title-row">
                  <div className="rp-step-title">Step {step.stepNum} — {def.title}{repIndex > 0 && <span className="rp-step-rep"> (ครั้งที่ {repIndex + 1})</span>}</div>
                  <button className="task-step-remove no-print" onClick={() => removeStepInstance(step.instanceId)} title="ลบ Step นี้"><X size={13} /></button>
                </div>
                {def.subOptions.length > 0 && (
                  <div className="rp-substep-list">
                    {def.subOptions.map((opt) => (
                      <label key={opt} className="authority-check">
                        <input type="checkbox" checked={step.subSteps.includes(opt)} onChange={() => {
                          const next = step.subSteps.includes(opt) ? step.subSteps.filter((s) => s !== opt) : [...step.subSteps, opt];
                          updateStepInstance(step.instanceId, { subSteps: next });
                        }} /> {opt}
                      </label>
                    ))}
                    {def.allowCustomSub && (
                      <input type="text" placeholder="เพิ่มขั้นตอนอื่นระบุ" value={step.customSub || ""} onChange={(e) => updateStepInstance(step.instanceId, { customSub: e.target.value })} style={{ maxWidth: 220 }} />
                    )}
                  </div>
                )}
                {def.productTypeOptions && (
                  <div className="rp-substep-list">
                    {def.productTypeOptions.map((opt) => (
                      <label key={opt} className="authority-check">
                        <input type="radio" name={`rp-pt-${step.instanceId}`} checked={step.productType === opt} onChange={() => updateStepInstance(step.instanceId, { productType: opt })} /> {opt}
                      </label>
                    ))}
                  </div>
                )}
                {def.qtyFields.length > 0 && (
                  <div className="rp-qty-grid">
                    {def.qtyFields.map((qf) => (
                      <div key={qf.key}>
                        <label className="field-label">{qf.label}</label>
                        <input type="number" value={step.qty[qf.key] || ""} onChange={(e) => updateStepInstance(step.instanceId, { qty: { ...step.qty, [qf.key]: e.target.value } })} />
                      </div>
                    ))}
                  </div>
                )}
                <div className="rp-timer-row no-print">
                  {!running ? (
                    <button className="btn btn-primary" onClick={() => startTimer(step.instanceId)}>▶ เริ่มจับเวลา</button>
                  ) : (
                    <button className="btn btn-outline rp-stop" onClick={() => stopTimer(step.instanceId)}>■ หยุด</button>
                  )}
                  <div className="rp-timer-display">{rpFmtTime(liveElapsed(step))}</div>
                  <button className="btn btn-outline" onClick={() => saveStepInstance(step.instanceId)}><Save size={13} /> บันทึก Step นี้</button>
                  {step.savedAt && <span className="badge badge-pos">บันทึกแล้ว</span>}
                </div>
              </div>
            );
          })}

          <div style={{ display: "flex", gap: ".5rem", justifyContent: "flex-end", marginTop: "1rem" }}>
            <button className="btn btn-primary no-print" onClick={finalSubmit}><CheckCircle2 size={14} /> บันทึกและส่งข้อมูลทั้งหมด</button>
          </div>
        </div>
      )}
    </div>
  );
}

/* ==================================================================== */
/* Staff Reward and Achievement — podium + race-track leaderboard         */
/* ==================================================================== */
const REWARD_TYPES = [
  { key: "all", label: "All Rewards and Achievement" },
  { key: "salesPerformance", label: "Sale Performance" },
  { key: "leadershipSegment", label: "Leadership Segment" },
  { key: "asicsIncentive", label: "Asics Incentive" },
];
const ASICS_INCENTIVE_RATE = 100; // baht per pair, from 1/09/2026, applies to full & discounted price
const RW_SLOT_SIZE = 5; // 1 track slot = 5 pairs
const RW_SLOT_COUNT = 20; // 20 slots = up to 100 pairs

function rwDateToISO(s) {
  const str = String(s || "").trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return str; // already ISO (new uploads store it this way)
  const m = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (!m) return null;
  const dd = m[1].padStart(2, "0"), mm = m[2].padStart(2, "0"), yyyy = m[3];
  return `${yyyy}-${mm}-${dd}`;
}
function rwIsoToDMY(iso) {
  const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return iso;
  return `${m[3]}/${m[2]}/${m[1]}`;
}
function rwNormalizeName(s) {
  return String(s || "").toUpperCase().replace(/\(.*?\)/g, "").replace(/[^A-Z0-9]/g, "").trim();
}
function rwMatchTransactions(transactions, employeeName) {
  const norm = rwNormalizeName(employeeName);
  if (!norm) return [];
  return transactions.filter((t) => {
    const tn = rwNormalizeName(t.salesPerson || t.salesPersonCode);
    if (!tn) return false;
    return tn === norm || tn.includes(norm) || norm.includes(tn);
  });
}

function RwHoverName({ name, tooltip }) {
  const [show, setShow] = useState(false);
  return (
    <span className="rw-hover-wrap" onMouseEnter={() => setShow(true)} onMouseLeave={() => setShow(false)} onClick={() => setShow((s) => !s)}>
      {name}
      {show && <div className="rw-tooltip">{tooltip}</div>}
    </span>
  );
}

function RwRaceLane({ rank, name, pctFinal, tooltip, valueLabel }) {
  const [pct, setPct] = useState(0);
  useEffect(() => {
    setPct(0);
    const id = setTimeout(() => setPct(pctFinal), 60);
    return () => clearTimeout(id);
  }, [pctFinal]);
  return (
    <div className="rw-race-lane">
      <div className="rw-race-name"><RwHoverName name={`${rank}. ${name}`} tooltip={tooltip} /></div>
      <div className="rw-race-lane-track">
        <div className="rw-race-runner" style={{ left: `calc(${pct}% - 14px)` }}>🏃</div>
      </div>
      <div className="rw-race-value">{valueLabel}</div>
    </div>
  );
}

function RwSegmentDots({ total, success }) {
  const dots = [];
  for (let i = 0; i < total; i++) dots.push(i < success ? "ok" : "no");
  return (
    <div className="rw-seg-dots">
      {dots.map((d, i) => <span key={i} className={`rw-seg-dot rw-seg-dot-${d}`} />)}
    </div>
  );
}

function StaffRewardWidget({ ctx }) {
  const [rewardType, setRewardType] = useState("salesPerformance");
  const [podiumLabels, setPodiumLabels] = useState(["🥇 อันดับ 1", "🥈 อันดับ 2", "🥉 อันดับ 3"]);

  const leadershipFiltered = useMemo(
    () => ctx.rewardLeadership.filter((r) => !r.isStoreTotal && (ctx.store === "ALL" || storeCodeToName(r.storeCode) === ctx.store)),
    [ctx.rewardLeadership, ctx.store]
  );
  const txFiltered = useMemo(() => {
    const dateSet = new Set(ctx.dates);
    return ctx.rewardTransactions.filter((t) => {
      if (ctx.store !== "ALL" && t.store.trim().toUpperCase() !== ctx.store.trim().toUpperCase()) return false;
      const iso = rwDateToISO(t.salesDate);
      return iso && dateSet.has(iso);
    });
  }, [ctx.rewardTransactions, ctx.store, ctx.dates]);

  const computeRows = useCallback((type) => {
    if (type === "asicsIncentive") {
      const base = rwAsicsIncentive(txFiltered, ASICS_INCENTIVE_RATE);
      return base.map((r) => {
        const details = txFiltered.filter((t) => t.brand.toUpperCase().includes("ASICS") && (t.salesPersonCode || t.salesPerson || "-") === r.key);
        return { name: r.salesPerson, value: r.incentive, qty: r.qty, unit: "บาท", details };
      });
    }
    if (type === "leadershipSegment") {
      return leadershipFiltered.map((r) => ({ name: r.employee, value: r.successPct ?? 0, unit: "%", raw: r })).sort((a, b) => b.value - a.value);
    }
    // Sale Performance — built straight from the transaction sheet, grouped by
    // Sales Person Code (falls back to the Sales Person name if no code).
    const map = new Map();
    const totalBillSet = new Set();
    txFiltered.forEach((t) => {
      totalBillSet.add(t.receiptNo);
      const key = t.salesPersonCode || t.salesPerson || "-";
      if (!key || key === "-") return;
      if (!map.has(key)) map.set(key, { name: t.salesPerson || t.salesPersonCode, value: 0, receipts: new Set() });
      const g = map.get(key);
      g.value += t.netSales;
      g.receipts.add(t.receiptNo);
    });
    const totalBills = totalBillSet.size;
    return Array.from(map.values())
      .map((g) => ({ name: g.name, value: g.value, unit: "บาท", billCount: g.receipts.size, totalBills }))
      .sort((a, b) => b.value - a.value);
  }, [leadershipFiltered, txFiltered]);

  const rows = useMemo(() => (rewardType === "all" ? [] : computeRows(rewardType)), [rewardType, computeRows]);
  const allBoard = useMemo(() => {
    if (rewardType !== "all") return [];
    return REWARD_TYPES.filter((t) => t.key !== "all").map((t) => ({ label: t.label, rows: computeRows(t.key).slice(0, 3) }));
  }, [rewardType, computeRows]);

  const maxValue = rows.length ? Math.max(...rows.map((r) => r.value)) : 0;
  const top3 = [rows[0], rows[1], rows[2]];
  const podiumOrder = [{ r: top3[1], rank: 2 }, { r: top3[0], rank: 1 }, { r: top3[2], rank: 3 }];

  const fmtVal = (r) => (r.unit === "%" ? `${r.value.toFixed(1)}%` : `${num(r.value)} บาท`);

  const tooltipFor = (r) => {
    if (rewardType === "salesPerformance") {
      const pct = r.totalBills > 0 ? ((r.billCount || 0) / r.totalBills) * 100 : 0;
      return (
        <div>
          <b>{r.name}</b>
          <div>{num(r.billCount || 0)} Bill/Success Mix{pct.toFixed(0)}%</div>
        </div>
      );
    }
    if (rewardType === "leadershipSegment" && r.raw) {
      return (
        <div>
          <b>{r.name}</b>
          <div>Sale Actual: {num(r.raw.salesActual)} บาท</div>
          <div>Sale Trans: {num(r.raw.salesTrans)}</div>
          <div>ATV: {num(r.raw.atv)}</div>
          <div>UPT: {num(r.raw.upt)}</div>
          <div>CR: {r.raw.convPct != null ? `${r.raw.convPct.toFixed(1)}%` : "-"}</div>
        </div>
      );
    }
    if (rewardType === "asicsIncentive" && r.details) {
      return (
        <div>
          <b>{r.name}</b>
          {r.details.length > 0 ? (
            <ul className="rw-tooltip-list">
              {r.details.slice(0, 10).map((d, i) => <li key={i}>{d.salesDate} · {d.sku} · {d.qty} ชิ้น</li>)}
            </ul>
          ) : <div className="rw-tooltip-muted">ไม่พบรายการ</div>}
        </div>
      );
    }
    return <div><b>{r.name}</b><div>{fmtVal(r)}</div></div>;
  };

  return (
    <div>
      <div className="rw-filter-row no-print">
        <div>
          <label className="field-label">สาขา</label>
          <div className="store-locked-badge">{ctx.store === "ALL" ? "ทุกสาขา" : ctx.store}</div>
        </div>
        <div>
          <label className="field-label">Reward and Incentive</label>
          <select value={rewardType} onChange={(e) => setRewardType(e.target.value)}>
            {REWARD_TYPES.map((t) => <option key={t.key} value={t.key}>{t.label}</option>)}
          </select>
        </div>
        <div>
          <label className="field-label">Data Range (กรองจริงตามนี้)</label>
          <div className="rw-period-badge">{rwIsoToDMY(ctx.from)} — {rwIsoToDMY(ctx.to)}</div>
        </div>
      </div>
      {ctx.rewardPeriod && <div className="widget-note" style={{ marginBottom: ".5rem" }}>ไฟล์ที่อัปโหลดล่าสุดระบุช่วง Sales Leadership ไว้ที่: {ctx.rewardPeriod}</div>}
      {rewardType === "asicsIncentive" && (
        <div className="widget-note" style={{ marginBottom: ".8rem" }}>Asics Incentive: คู่ละ 100 บาท เริ่มวันที่ 1/09/2026 ร่วมรายการทั้งราคาเต็มและราคาลด · เส้นทางแบ่งเป็น 20 ช่อง ช่องละ 5 คู่ (กรองตามสาขาและช่วงวันที่ที่เลือกในตัวกรองหลักด้านซ้าย)</div>
      )}

      {rewardType === "all" ? (
        <div className="rw-scoreboard">
          <div className="rw-scoreboard-title">ALL REWARDS AND ACHIEVEMENT</div>
          {allBoard.map((cat, i) => (
            <div className="rw-scoreboard-row" key={i}>
              <div className="rw-scoreboard-cat">{cat.label}</div>
              <div className="rw-scoreboard-ranks">
                {[0, 1, 2].map((idx) => {
                  const r = cat.rows[idx];
                  const medal = idx === 0 ? "🥇" : idx === 1 ? "🥈" : "🥉";
                  return (
                    <div className="rw-scoreboard-rank" key={idx}>
                      <span className="rw-scoreboard-medal">{medal}</span>
                      {r ? (
                        <>
                          <span className="rw-scoreboard-name">{r.name}</span>
                          <span className="rw-scoreboard-value">{r.unit === "%" ? `${r.value.toFixed(1)}%` : `${num(r.value)} บาท`}</span>
                        </>
                      ) : <span className="rw-scoreboard-name">—</span>}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
          {allBoard.every((cat) => cat.rows.length === 0) && <div className="empty-hint">ยังไม่มีข้อมูลสำหรับตัวกรองนี้ — อัปโหลดไฟล์ที่ YOUR SOURCE ก่อน</div>}
        </div>
      ) : rows.length === 0 ? (
        <div className="empty-hint">ยังไม่มีข้อมูลสำหรับตัวกรองนี้ — อัปโหลดไฟล์ที่ YOUR SOURCE ก่อน</div>
      ) : (
        <>
          <div className="rw-podium">
            {podiumOrder.map(({ r, rank }, i) => (
              <div className={`rw-podium-slot rw-podium-${rank}`} key={i}>
                <input className="rw-podium-label-input no-print" value={podiumLabels[rank - 1]} onChange={(e) => { const next = [...podiumLabels]; next[rank - 1] = e.target.value; setPodiumLabels(next); }} />
                {r ? (<>
                  <div className="rw-podium-name"><RwHoverName name={r.name} tooltip={tooltipFor(r)} /></div>
                  <div className="rw-podium-value">{fmtVal(r)}</div>
                </>) : <div className="rw-podium-name">—</div>}
                <div className="rw-podium-bar" />
              </div>
            ))}
          </div>

          {rewardType === "leadershipSegment" ? (
            <div className="rw-seg-list">
              {rows.map((r, i) => (
                <div className="rw-seg-row" key={i}>
                  <div className="rw-seg-name"><RwHoverName name={`${i + 1}. ${r.name}`} tooltip={tooltipFor(r)} /></div>
                  <RwSegmentDots total={r.raw?.segTotal || 0} success={r.raw?.segSuccess || 0} />
                  <div className="rw-seg-pct">{r.raw?.segTotal ? `${r.raw.segSuccess}/${r.raw.segTotal}` : "-"} · {r.value.toFixed(1)}%</div>
                </div>
              ))}
            </div>
          ) : (
            <div className="rw-race-track">
              {rows.map((r, i) => {
                const isAsics = rewardType === "asicsIncentive";
                const pct = isAsics
                  ? (Math.min(RW_SLOT_COUNT, Math.ceil((r.qty || 0) / RW_SLOT_SIZE)) / RW_SLOT_COUNT) * 100
                  : (maxValue > 0 ? Math.min(100, (r.value / maxValue) * 100) : 0);
                return (
                  <RwRaceLane
                    key={i}
                    rank={i + 1}
                    name={r.name}
                    pctFinal={pct}
                    tooltip={tooltipFor(r)}
                    valueLabel={isAsics ? `${num(r.qty || 0)} คู่` : fmtVal(r)}
                  />
                );
              })}
            </div>
          )}
        </>
      )}
    </div>
  );
}

